# Uploads are deliberately bounded independently from GPU/model lanes.  A
# handful of concurrent clients may ingest at once, while only two ffmpeg
# workers can compete for CPU, disk and decoder resources.  Waiting on these
# semaphores is cancellable and never holds a global application lock.
_UPLOAD_INGEST_SLOTS = asyncio.Semaphore(4)
_UPLOAD_TRANSCODE_SLOTS = asyncio.Semaphore(2)


async def _stream_upload(upload, destination: str, *, max_bytes: int) -> int:
    async with _UPLOAD_INGEST_SLOTS:
        return await stream_upload_file(
            upload,
            destination,
            max_bytes=max_bytes,
        )


async def _transcode_upload(source: str, destination: str, *, is_video: bool) -> None:
    async with _UPLOAD_TRANSCODE_SLOTS:
        await transcode_upload(source, destination, is_video=is_video)


def _safe_join(base: str, *parts: str) -> str | None:
    """Join `parts` under `base` and return the absolute path only if it
    stays inside `base`. Returns None on traversal attempts (`..`, absolute
    paths, symlinks escaping the base, etc.). Use for any endpoint that
    accepts a user-supplied filename."""
    try:
        base_real = os.path.realpath(base)
        joined = os.path.realpath(os.path.join(base_real, *parts))
        # commonpath compares path components rather than string prefixes.
        # normcase preserves correct behaviour on case-insensitive Windows
        # filesystems and ValueError handles paths on different drives.
        base_cmp = os.path.normcase(base_real)
        joined_cmp = os.path.normcase(joined)
        if os.path.commonpath((base_cmp, joined_cmp)) != base_cmp:
            return None
        return joined
    except (ValueError, OSError):
        return None


def _resolve_output_move_path(base: str, relative_name: str) -> str | None:
    """Resolve one output path for a cross-workspace move.

    The move endpoint accepts a path parameter, so it needs a stricter
    contract than a generic join: only explicit relative components using
    URL separators are accepted. Both source and destination are then
    resolved through ``_safe_join`` so existing symlinks cannot escape their
    workspace.
    """
    if not isinstance(relative_name, str):
        return None
    value = relative_name.strip()
    if not value or "\x00" in value or "\\" in value:
        return None
    drive, _tail = os.path.splitdrive(value)
    if drive or os.path.isabs(value):
        return None
    parts = value.split("/")
    if any(part in {"", ".", ".."} for part in parts):
        return None
    resolved = _safe_join(base, *parts)
    if not resolved or resolved == os.path.realpath(base):
        return None
    return resolved

# CORS — restricted to localhost (the Vite dev server + the bundled UI
# served from the same FastAPI process + Pinokio's HTTPS proxy at
# https://<port>.localhost). Do NOT loosen this to `*`: browser access stays
# intentionally same-origin even when LAN session authentication is enabled.
_cors_origin_regex = r"^https?://(127\.0\.0\.1|localhost|\d+\.localhost)(:\d+)?$"
api.add_middleware(
    CORSMiddleware,
    allow_origin_regex=_cors_origin_regex,
    allow_methods=["*"],
    allow_headers=["*"],
)
api.include_router(create_lan_auth_router())


@api.middleware("http")
async def protect_cross_origin_mutations(request: Request, call_next):
    """Reject browser mutations from a different origin, including on LAN."""
    if request.method in {"POST", "PUT", "PATCH", "DELETE"}:
        origin = request.headers.get("origin")
        if origin:
            from urllib.parse import urlsplit

            try:
                origin_host = (urlsplit(origin).netloc or "").casefold()
            except ValueError:
                origin_host = ""
            request_host = str(request.headers.get("host") or "").casefold()
            local_hosts = {"localhost", "127.0.0.1", "[::1]"}
            origin_name = origin_host.rsplit(":", 1)[0]
            request_name = request_host.rsplit(":", 1)[0]
            same_origin_host = bool(origin_host and origin_host == request_host)
            local_proxy = origin_name in local_hosts and request_name in local_hosts
            pinokio_proxy = bool(re.fullmatch(r"\d+\.localhost(?::\d+)?", origin_host))
            if not (same_origin_host or local_proxy or pinokio_proxy):
                return JSONResponse(
                    status_code=403,
                    content={"detail": "Cross-origin API mutations are not allowed"},
                )
    return await call_next(request)


@api.middleware("http")
async def trace_user_mutations(request: Request, call_next):
    """Record reconstructible user/API actions while debug tracing is on."""
    should_trace = (
        debug_trace.is_enabled()
        and request.method in {"POST", "PUT", "PATCH", "DELETE"}
        and request.url.path != "/api/v1/debug/user-action"
    )
    event_id = uuid.uuid4().hex if should_trace else ""
    started = time.monotonic()
    if should_trace:
        content_type = request.headers.get("content-type", "")
        request_body = None
        if "application/json" in content_type:
            try:
                raw_body = await request.body()
                request_body = json.loads(raw_body) if raw_body else None
            except Exception as exc:
                request_body = {"parse_error": str(exc)}
        elif content_type:
            request_body = f"<{content_type}; body omitted>"
        from services.task_manager import redact_sensitive_data

        debug_trace.trace_event(
            "user_action", "api_request", event_id=event_id, phase="request",
            method=request.method, path=request.url.path,
            query=redact_sensitive_data(dict(request.query_params)),
            body=redact_sensitive_data(request_body),
        )
    try:
        with debug_trace.context_scope(
            request_id=event_id or None,
            http_method=request.method,
            http_path=request.url.path,
        ):
            response = await call_next(request)
    except Exception as exc:
        if should_trace:
            debug_trace.trace_event(
                "user_action", "api_request", event_id=event_id, phase="error",
                method=request.method, path=request.url.path,
                duration_ms=round((time.monotonic() - started) * 1000, 2),
                error={"type": type(exc).__name__, "message": str(exc)},
            )
        raise
    if should_trace:
        debug_trace.trace_event(
            "user_action", "api_request", event_id=event_id, phase="response",
            method=request.method, path=request.url.path,
            status_code=response.status_code,
            duration_ms=round((time.monotonic() - started) * 1000, 2),
        )
    return response


