def _normalize_comic_panel_arrays(panel: dict) -> None:
    """Repair common single-item JSON shortcuts without discarding copy."""
    for key in ("characters", "captions", "soundEffects"):
        value = panel.get(key)
        if isinstance(value, list):
            continue
        if isinstance(value, str) and value.strip():
            panel[key] = [value.strip()]
        else:
            panel[key] = []

    value = panel.get("dialogue")
    if isinstance(value, list):
        items = value
    elif isinstance(value, dict):
        items = [value]
    elif isinstance(value, str) and value.strip():
        items = [{"text": value.strip(), "bubbleType": "speech"}]
    else:
        items = []
    panel["dialogue"] = [
        {"text": item.strip(), "bubbleType": "speech"}
        if isinstance(item, str) and item.strip()
        else item
        for item in items
        if isinstance(item, dict) or (isinstance(item, str) and item.strip())
    ]


def _normalize_comic_panel_character_ids(panel: dict, characters: list) -> None:
    """Resolve harmless LLM name/ID drift while preserving visual priority order."""
    lookup: dict[str, str] = {}
    canonical_ids: set[str] = set()
    for character in characters:
        if not isinstance(character, dict):
            continue
        canonical = str(character.get("id") or "").strip()
        if not canonical:
            continue
        canonical_ids.add(canonical)
        for alias in (character.get("id"), character.get("name")):
            value = str(alias or "").strip()
            if value:
                lookup.setdefault(value.casefold(), canonical)
                token = re.sub(r"[^a-z0-9]+", "-", value.casefold()).strip("-")
                if token:
                    lookup.setdefault(token, canonical)

    normalized: list[str] = []
    for value in panel.get("characters", []):
        stripped = str(value or "").strip()
        token = re.sub(r"[^a-z0-9]+", "-", stripped.casefold()).strip("-")
        canonical = (
            stripped
            if stripped in canonical_ids
            else lookup.get(stripped.casefold()) or lookup.get(token)
        )
        if canonical and canonical not in normalized:
            normalized.append(canonical)
    panel["characters"] = normalized


def _comic_page_problem(page, expected_panels: int) -> str | None:
    """Return why a generated page is unsafe to checkpoint, if anything."""
    if not isinstance(page, dict):
        return "the page is not a JSON object"
    panels = page.get("panels")
    if not isinstance(panels, list):
        return "the panels field is not an array"
    if len(panels) != expected_panels:
        return f"it contains {len(panels)} panels instead of {expected_panels}"
    for panel_index, panel in enumerate(panels, 1):
        if not isinstance(panel, dict):
            return f"panel {panel_index} is not a JSON object"
        _normalize_comic_panel_arrays(panel)
        dialogue = panel.get("dialogue")
        if not isinstance(dialogue, list):
            return f"panel {panel_index} dialogue is not an array"
        if any(not isinstance(line, dict) for line in dialogue):
            return f"panel {panel_index} contains malformed dialogue"
        normalized_lines = [
            str(line.get("text") or "").strip().casefold()
            for line in dialogue
            if str(line.get("text") or "").strip()
        ]
        if len(normalized_lines) > 2:
            return f"panel {panel_index} contains excessive dialogue"
        if normalized_lines and len(set(normalized_lines)) < len(normalized_lines) * 0.6:
            return f"panel {panel_index} contains repetitive dialogue"
    return None


def _storyboard_page_problem(page, expected_panels: int = 1) -> str | None:
    """Validate video-specific fields after the shared comic shape is safe."""
    problem = _comic_page_problem(page, expected_panels)
    if problem:
        return problem
    for panel_index, panel in enumerate(page["panels"], 1):
        if not str(panel.get("imagePrompt") or "").strip():
            return f"shot {panel_index} has no first-frame image prompt"
        video_prompt = str(panel.get("videoPrompt") or "").strip()
        if not video_prompt:
            return f"shot {panel_index} has no video motion prompt"
        if len(video_prompt) > 1400:
            return f"shot {panel_index} video prompt is too long"
        try:
            duration = float(panel.get("durationSeconds"))
        except (TypeError, ValueError):
            return f"shot {panel_index} durationSeconds is not a number"
        if duration < 0.8 or duration > 20:
            return f"shot {panel_index} durationSeconds is outside 0.8–20 seconds"
        if panel.get("cameraMove") not in {
            "none", "push-in", "pull-out", "pan-left", "pan-right",
        }:
            return f"shot {panel_index} cameraMove is invalid"
        if panel.get("captions") or panel.get("dialogue") or panel.get("soundEffects"):
            return f"shot {panel_index} contains lettering instead of a clean video frame"
    return None


def _compact_comic_panel_copy(
    panel: dict,
    dialogue_limit: int = 1,
    max_elements: int = 2,
) -> None:
    """Keep generated lettering readable even when the planning model overproduces."""
    seen = set()

    def unique_text(values, limit):
        if limit <= 0:
            return []
        compacted = []
        for value in values if isinstance(values, list) else []:
            text = str(value or "").strip()
            key = re.sub(r"\s+", " ", text).casefold()
            if not key or key in seen:
                continue
            seen.add(key)
            compacted.append(text)
            if len(compacted) >= limit:
                break
        return compacted

    panel["captions"] = unique_text(panel.get("captions"), min(1, max_elements))
    dialogue = []
    dialogue_limit = min(dialogue_limit, max(0, max_elements - len(panel["captions"])))
    for value in panel.get("dialogue") if isinstance(panel.get("dialogue"), list) else []:
        if not isinstance(value, dict):
            continue
        text = str(value.get("text") or "").strip()
        key = re.sub(r"\s+", " ", text).casefold()
        if not key or key in seen:
            continue
        seen.add(key)
        dialogue.append({**value, "text": text})
        if len(dialogue) >= dialogue_limit:
            break
    panel["dialogue"] = dialogue
    remaining_lettering_slots = max(
        0,
        max_elements - len(panel["captions"]) - len(panel["dialogue"]),
    )
    panel["soundEffects"] = unique_text(panel.get("soundEffects"), remaining_lettering_slots)


def _enforce_comic_page_text_budget(page: dict, dialogue_density: str) -> None:
    panels = page.get("panels") if isinstance(page, dict) else None
    if not isinstance(panels, list) or not panels:
        return
    dense_grid = len(panels) >= 7
    for panel_index, panel in enumerate(panels):
        if isinstance(panel, dict):
            is_large_panel = (
                len(panels) <= 4
                or (page.get("layoutHint") == "dynamic" and panel_index == 0)
            )
            _compact_comic_panel_copy(
                panel,
                dialogue_limit=1 if dense_grid else (2 if dialogue_density == "high" else 1),
                max_elements=2 if is_large_panel else 1,
            )
    ratio = {"low": 0.3, "medium": 0.55, "high": 0.8}.get(dialogue_density, 0.55)
    keep_count = max(1, min(len(panels), int(len(panels) * ratio + 0.999)))
    text_panel_indices = [
        index
        for index, panel in enumerate(panels)
        if isinstance(panel, dict) and (
            panel.get("captions") or panel.get("dialogue") or panel.get("soundEffects")
        )
    ]
    if len(text_panel_indices) <= keep_count:
        return
    if keep_count == 1:
        keep = {text_panel_indices[0]}
    else:
        keep = {
            text_panel_indices[
                round(position * (len(text_panel_indices) - 1) / (keep_count - 1))
            ]
            for position in range(keep_count)
        }
    for index, panel in enumerate(panels):
        if isinstance(panel, dict) and index not in keep:
            panel["captions"] = []
            panel["dialogue"] = []
            panel["soundEffects"] = []


_COMIC_ENGLISH_DRIFT_WORDS = {
    "the", "this", "that", "these", "those", "is", "are", "was", "were",
    "be", "been", "being", "and", "but", "with", "without", "from", "into",
    "nothing", "everything", "silence", "absolute", "measurement", "truth",
    "lie", "void", "world", "future", "power", "freedom", "insignificant",
    "we", "you", "your", "our", "they", "their", "not", "never", "always",
}


def _comic_page_has_probable_english_drift(page: dict, target_language: str) -> bool:
    language = str(target_language or "").strip().lower()
    if not language or language in {"english", "ingles", "inglés", "en", "en-us", "en-gb"}:
        return False
    hits = 0
    suspicious_lines = 0
    for panel in page.get("panels") or []:
        if not isinstance(panel, dict):
            continue
        reader_lines = [str(value) for value in (panel.get("captions") or [])]
        reader_lines.extend(
            str(item.get("text") or "")
            for item in (panel.get("dialogue") or [])
            if isinstance(item, dict)
        )
        for line in reader_lines:
            words = re.findall(r"[A-Za-zÀ-ÖØ-öø-ÿ']+", line.lower())
            line_hits = sum(word in _COMIC_ENGLISH_DRIFT_WORDS for word in words)
            hits += line_hits
            if line_hits >= 2:
                suspicious_lines += 1
    return suspicious_lines > 0 or hits >= 4


def _comic_page_summary(page) -> str:
    if not isinstance(page, dict):
        return ""
    panels = page.get("panels")
    if not isinstance(panels, list):
        return ""
    beats = []
    for panel in panels:
        if not isinstance(panel, dict):
            continue
        beat = str(
            panel.get("continuityNotes")
            or panel.get("sceneDescription")
            or panel.get("narrativeRole")
            or ""
        ).strip()
        if beat:
            beats.append(beat)
    return " ".join(beats)[-1600:]


def _parse_comic_director_json(
    raw,
    stage: str,
    *,
    root_array_key: str | None = None,
) -> dict:
    if not isinstance(raw, str) or not raw.strip():
        raise RuntimeError(f"LLM returned no text while {stage}")
    cleaned = raw.strip()
    if cleaned.startswith("```"):
        cleaned = cleaned.strip("`")
        if cleaned.lower().startswith("json"):
            cleaned = cleaned[4:].lstrip()
    try:
        parsed = json.loads(cleaned)
    except json.JSONDecodeError as parse_error:
        from json_repair import repair_json
        print(
            f"[Comic Director] Repairing malformed {stage} JSON "
            f"at line {parse_error.lineno}, column {parse_error.colno}"
        )
        parsed = repair_json(cleaned, return_objects=True)
    # Some OpenAI-compatible providers occasionally honor an object schema by
    # returning either a one-item array or JSON encoded as a JSON string.
    # Normalize those losslessly before spending another provider request.
    if isinstance(parsed, str):
        nested = parsed.strip()
        if nested and nested != cleaned:
            try:
                parsed = json.loads(nested)
            except json.JSONDecodeError:
                from json_repair import repair_json
                parsed = repair_json(nested, return_objects=True)
    if not root_array_key and isinstance(parsed, list) and len(parsed) == 1:
        sole_item = parsed[0]
        if isinstance(sole_item, dict):
            print(f"[Comic Director] Unwrapped one-item array while {stage}")
            parsed = sole_item
    if root_array_key and isinstance(parsed, list):
        print(
            f"[Comic Director] Wrapped top-level array as "
            f"{root_array_key!r} while {stage}"
        )
        parsed = {root_array_key: parsed}
    if not isinstance(parsed, dict):
        raise ValueError(f"LLM response for {stage} is not a JSON object")
    return _repair_comic_text_encoding(parsed)


def _repair_comic_text_encoding(value):
    """Repair UTF-8 bytes that an older SSE decoder treated as Latin-1."""
    if isinstance(value, dict):
        return {key: _repair_comic_text_encoding(item) for key, item in value.items()}
    if isinstance(value, list):
        return [_repair_comic_text_encoding(item) for item in value]
    if not isinstance(value, str) or not any(marker in value for marker in ("Ã", "Â", "â")):
        return value
    try:
        repaired = value.encode("latin-1").decode("utf-8")
        return repaired if repaired != value else value
    except (UnicodeEncodeError, UnicodeDecodeError):
        return value


def _generate_comic_director_json(
    *,
    prompt: str,
    system_prompt: str,
    schema: dict,
    max_new_tokens: int,
    stage: str,
    llm_override: dict | None = None,
    root_array_key: str | None = None,
    image_paths: list[str] | None = None,
) -> dict:
    from services import llm_service
    # A streaming HTTP response resets the read timeout on every token.
    # This lets slow CPU-hosted Ollama models finish healthy generations
    # instead of losing all work after one ten-minute blocking request.
    common = {
        "prompt": prompt,
        "system_prompt": system_prompt,
        "max_new_tokens": max_new_tokens,
        "temperature": 0.2,
        "frequency_penalty": 0.25,
        "presence_penalty": 0.1,
        "json_schema": schema,
        "image_paths": image_paths or [],
    }
    parse_error = None
    for attempt in range(1, 3):
        request = dict(common)
        if parse_error is not None:
            # Remote OpenAI-compatible providers are stateless: they do not
            # know what they emitted on the previous request.  Give the
            # correction pass the actual response, rather than asking it to
            # regenerate the whole document from scratch.  The cap prevents
            # a pathological provider response from turning recovery into an
            # unbounded prompt-token bill.
            previous_response = raw.strip()
            previous_limit = 16000
            if len(previous_response) > previous_limit:
                previous_response = (
                    previous_response[:previous_limit]
                    + "\n[previous response truncated for bounded JSON repair]"
                )
            request["prompt"] = (
                f"{prompt}\n\nJSON CORRECTION RETRY: Your previous response could not be "
                "decoded as the required JSON object. Preserve every usable fact from the "
                "previous response and repair only its JSON structure. Return exactly one "
                "complete JSON object matching the supplied schema, with no prose, markdown "
                "or outer array.\n\nPREVIOUS RESPONSE TO REPAIR:\n"
                f"{previous_response}"
            )
            print(f"[Comic Director] Retrying malformed {stage} response once")
        if llm_override:
            raw = llm_service.generate_openai_compatible(
                **request,
                model_id=llm_override["model"],
                base_url=llm_override["base_url"],
                api_key=llm_override["api_key"],
            )
        else:
            raw = llm_service.generate_streaming(
                **request,
                enable_thinking=False,
                thinking_budget=0,
            )
        try:
            return _parse_comic_director_json(
                raw,
                f"{stage}, attempt {attempt}",
                root_array_key=root_array_key,
            )
        except (ValueError, json.JSONDecodeError) as exc:
            parse_error = exc
            if attempt >= 2:
                raise
    raise parse_error  # pragma: no cover - the loop always returns or raises


def _comic_writing_llm(body: dict) -> dict | None:
    """Resolve a comic-only LLM override without changing global LLM state."""
    provider = str(body.get("writingProvider") or "maestro").strip().lower()
    if provider in ("", "maestro", "internal", "local"):
        return None
    if provider not in ("deepseek", "minimax", "openai", "openai-compatible"):
        raise HTTPException(status_code=400, detail="Unsupported comic writing provider")

    services = wgp.server_config.get("services", {})
    requested_url = str(body.get("writingBaseUrl") or "").strip()[:1000]
    # Projects created before provider profiles existed stored DeepSeek/OpenAI
    # as a generic compatible endpoint. Route those projects to the matching
    # named profile, but never migrate or copy credentials between providers.
    if provider == "openai-compatible":
        from urllib.parse import urlparse
        legacy_host = (urlparse(requested_url).hostname or "").lower()
        if legacy_host == "api.deepseek.com":
            provider = "deepseek"
        elif legacy_host == "api.openai.com":
            provider = "openai"

    if provider == "deepseek":
        model = str(body.get("writingModel") or "deepseek-v4-pro").strip()[:200]
        if model in ("", "deepseek-chat", "deepseek-reasoner"):
            model = "deepseek-v4-pro"
        if str(body.get("mode") or "").lower() == "translate":
            model = "deepseek-v4-flash"
        if model not in {"deepseek-v4-pro", "deepseek-v4-flash"}:
            raise HTTPException(status_code=400, detail="Choose DeepSeek V4 Pro or V4 Flash")
        base_url = "https://api.deepseek.com"
        api_key = str(services.get("deepseek_api_key") or "")
        if not api_key:
            raise HTTPException(
                status_code=400,
                detail="Configure the DeepSeek API key in Settings → Services first",
            )
    elif provider == "minimax":
        model = str(body.get("writingModel") or "MiniMax-M3").strip()[:200]
        allowed_models = {"MiniMax-M3", "MiniMax-M2.7", "MiniMax-M2.7-highspeed"}
        if model not in allowed_models:
            raise HTTPException(
                status_code=400,
                detail="Choose MiniMax M3, M2.7, or M2.7 Highspeed",
            )
        base_url = "https://api.minimax.io/v1"
        api_key = str(services.get("minimax_api_key") or "")
        if not api_key:
            raise HTTPException(
                status_code=400,
                detail="Configure the MiniMax API key in Settings → Services first",
            )
    elif provider == "openai":
        model = str(body.get("writingModel") or "gpt-4.1").strip()[:200]
        base_url = "https://api.openai.com"
        api_key = str(services.get("openai_api_key") or "")
        if not api_key:
            raise HTTPException(
                status_code=400,
                detail="Configure the OpenAI API key in Settings → Services first",
            )
    else:
        model = str(body.get("writingModel") or "").strip()[:200]
        base_url = str(services.get("compatible_base_url") or "").strip()[:1000].rstrip("/")
        if not base_url:
            raise HTTPException(
                status_code=400,
                detail="Configure the custom compatible URL in Settings → Services first",
            )
        if requested_url and requested_url.rstrip("/") != base_url:
            raise HTTPException(
                status_code=400,
                detail="The comic's custom URL does not match the trusted compatible profile",
            )
        api_key = str(services.get("compatible_api_key") or "")

    if not base_url.startswith(("http://", "https://")):
        raise HTTPException(
            status_code=400,
            detail="OpenAI-compatible URL must start with http:// or https://",
        )
    if not model:
        raise HTTPException(status_code=400, detail="Choose an OpenAI-compatible model")
    return {
        "provider": provider,
        "model": model,
        "base_url": base_url.rstrip("/"),
        "api_key": api_key,
    }


def _story_lab_schema(scope: str, project_type: str = "full_story") -> dict:
    """Return the strict editable Story Lab payload requested for one stage."""
    string = {"type": "string"}
    string_array = {"type": "array", "items": string, "maxItems": 12}
    location = {
        "type": "object",
        "properties": {
            "id": string, "name": string, "purpose": string, "description": string,
            "visualPrompt": string, "negativePrompt": string,
        },
        "required": [
            "id", "name", "purpose", "description", "visualPrompt", "negativePrompt",
        ],
        "additionalProperties": False,
    }
    world = {
        "type": "object",
        "properties": {
            "summary": string, "period": string, "geography": string,
            "society": string, "technology": string, "rules": string_array,
            "visualLanguage": string, "visualPrompt": string, "negativePrompt": string,
            "locations": {"type": "array", "items": location, "maxItems": 8},
        },
        "required": [
            "summary", "period", "geography", "society", "technology", "rules",
            "visualLanguage", "visualPrompt", "negativePrompt", "locations",
        ],
        "additionalProperties": False,
    }
    character = {
        "type": "object",
        "properties": {
            "id": string, "name": string, "role": string, "age": string,
            "pronouns": string, "personality": string, "desire": string,
            "need": string, "flaw": string, "conflict": string, "arc": string,
            "voice": string, "appearance": string, "wardrobe": string,
            "visualPrompt": string, "negativePrompt": string,
        },
        "required": [
            "id", "name", "role", "age", "pronouns", "personality", "desire",
            "need", "flaw", "conflict", "arc", "voice", "appearance", "wardrobe",
            "visualPrompt", "negativePrompt",
        ],
        "additionalProperties": False,
    }
    relationship = {
        "type": "object",
        "properties": {
            "id": string, "fromCharacterId": string, "toCharacterId": string,
            "label": string, "dynamic": string, "evolution": string,
        },
        "required": [
            "id", "fromCharacterId", "toCharacterId", "label", "dynamic", "evolution",
        ],
        "additionalProperties": False,
    }
    beat = {
        "type": "object",
        "properties": {
            "id": string, "stage": string, "title": string, "summary": string,
            "goal": string, "conflict": string, "turn": string,
        },
        "required": ["id", "stage", "title", "summary", "goal", "conflict", "turn"],
        "additionalProperties": False,
    }
    music_cue = {
        "type": "object",
        "properties": {
            "id": string,
            "kind": {"type": "string", "enum": ["world", "character", "story"]},
            "targetId": string,
            "title": string,
            "purpose": string,
            "referenceSong": string,
            "brief": string,
            "style": string,
            "lyrics": string,
            "instrumental": {"type": "boolean"},
            "durationSeconds": {"type": "integer", "minimum": 20, "maximum": 360},
        },
        "required": [
            "id", "kind", "targetId", "title", "purpose", "referenceSong",
            "brief", "style", "lyrics", "instrumental", "durationSeconds",
        ],
        "additionalProperties": False,
    }
    beat_minimum = 3 if project_type == "quick_video" else 4 if project_type == "music_video" else 6
    beat_maximum = 8 if project_type == "quick_video" else 10 if project_type == "music_video" else 12 if project_type == "trailer" else 14
    music_minimum = 1 if project_type == "music_video" else 4
    music_maximum = 1 if project_type == "music_video" else 16
    creative_brief = {
        "type": "object",
        "properties": {
            "generalIdea": string, "context": string, "performer": string,
            "musicStyle": string, "songStory": string, "subjects": string,
            "setting": string, "action": string,
            "quickFormat": {"type": "string", "enum": [
                "dialogue", "meme", "parody", "sketch", "viral", "announcement",
            ]},
            "durationSeconds": {"type": "integer", "minimum": 5, "maximum": 360},
        },
        "required": [
            "generalIdea", "context", "performer", "musicStyle", "songStory",
            "subjects", "setting", "action", "quickFormat", "durationSeconds",
        ],
        "additionalProperties": False,
    }
    properties = {
        "overview": {
            "type": "object",
            "properties": {
                "title": string, "creativeBrief": creative_brief,
                "language": string, "genre": string, "tone": string,
                "audience": string, "visualStyle": string,
                "characterVisualStyle": string,
                "enforceVisualStyle": {"type": "boolean"},
                "allowClipText": {"type": "boolean"},
                "musicVideoGenerationMode": {"type": "string", "enum": ["image_guided", "direct_video"]},
                "premise": string, "logline": string, "synopsis": string,
                "theme": string, "ending": string,
            },
            "required": [
                "title", "creativeBrief", "language", "genre", "tone", "audience",
                "visualStyle", "characterVisualStyle", "enforceVisualStyle",
                "allowClipText", "musicVideoGenerationMode", "premise", "logline",
                "synopsis", "theme", "ending",
            ],
            "additionalProperties": False,
        },
        "world": world,
        "characters": {"type": "array", "items": character, "minItems": 1, "maxItems": 12},
        "relationships": {"type": "array", "items": relationship, "maxItems": 24},
        "beats": {"type": "array", "items": beat, "minItems": beat_minimum, "maxItems": beat_maximum},
        "music": {
            "type": "object",
            "properties": {
                "cues": {"type": "array", "items": music_cue, "minItems": music_minimum, "maxItems": music_maximum},
            },
            "required": ["cues"],
            "additionalProperties": False,
        },
    }
    keys = list(properties) if scope == "all" else [scope]
    return {
        "type": "object",
        "properties": {key: properties[key] for key in keys},
        "required": keys,
        "additionalProperties": False,
    }


def _story_id_token(value) -> str:
    return re.sub(r"[^a-z0-9]+", "-", str(value or "").strip().casefold()).strip("-")


def _normalize_story_stage_ids(
    result: dict,
    scope: str,
    project: dict,
    *,
    drop_unknown_relationships: bool = False,
) -> dict:
    """Repair harmless LLM omissions and ID drift before validation."""
    normalized = copy.deepcopy(result)
    if scope == "structure" and isinstance(normalized, dict):
        # Smaller/local providers occasionally ignore the top-level JSON
        # schema while still returning a useful visual sequence. Preserve
        # that work instead of spending another full call asking for the same
        # story under the literal ``beats`` key.
        raw_beats = normalized.get("beats")
        if isinstance(raw_beats, dict):
            raw_beats = next((
                raw_beats.get(key)
                for key in ("items", "beats", "moments", "scenes", "sequences")
                if isinstance(raw_beats.get(key), list)
            ), raw_beats)

        visual_sequence = normalized.get("visual_sequence_outline")
        visual_sequence = visual_sequence if isinstance(visual_sequence, list) else []
        plot_points = normalized.get("plot_points")
        plot_points = plot_points if isinstance(plot_points, list) else []
        if not isinstance(raw_beats, list):
            raw_beats = next((
                normalized.get(key)
                for key in ("structure", "moments", "scenes", "sequences")
                if isinstance(normalized.get(key), list)
            ), None)
        if not isinstance(raw_beats, list):
            raw_beats = visual_sequence or plot_points

        if isinstance(raw_beats, list):
            def field(item, *keys):
                if not isinstance(item, dict):
                    return str(item or "").strip()
                return next((
                    str(item.get(key) or "").strip()
                    for key in keys if str(item.get(key) or "").strip()
                ), "")

            beats = []
            used_ids: set[str] = set()
            total = len(raw_beats)
            for index, item in enumerate(raw_beats):
                visual = visual_sequence[index] if index < len(visual_sequence) else {}
                plot = plot_points[index] if index < len(plot_points) else {}
                source = item if isinstance(item, dict) else {"description": item}
                title = (
                    field(source, "title", "name", "focus")
                    or field(plot, "title", "name", "focus")
                    or field(visual, "title", "name", "focus")
                    or f"Moment {index + 1}"
                )
                summary = (
                    field(visual, "summary", "description", "action", "visual")
                    or field(source, "summary", "description", "action", "visual")
                    or field(plot, "summary", "description", "action")
                    or title
                )
                goal = (
                    field(source, "goal", "objective", "purpose", "focus")
                    or field(plot, "goal", "objective", "purpose", "focus")
                    or title
                )
                conflict = (
                    field(source, "conflict", "obstacle", "tension", "problem")
                    or field(plot, "conflict", "obstacle", "tension", "description")
                    or summary
                )
                turn = (
                    field(source, "turn", "change", "outcome", "result", "reversal")
                    or field(plot, "turn", "change", "outcome", "result", "description")
                    or field(visual, "turn", "change", "outcome", "description")
                    or summary
                )
                stage = field(source, "stage", "section", "phase")
                if not stage:
                    stage = (
                        "setup" if index == 0 else
                        "resolution" if index == total - 1 else
                        "climax" if total > 2 and index == total - 2 else
                        "rising action"
                    )
                candidate = _story_id_token(field(source, "id") or title) or f"beat-{index + 1}"
                base = candidate
                suffix = 2
                while candidate in used_ids:
                    candidate = f"{base}-{suffix}"
                    suffix += 1
                used_ids.add(candidate)
                beats.append({
                    "id": candidate,
                    "stage": stage,
                    "title": title,
                    "summary": summary,
                    "goal": goal,
                    "conflict": conflict,
                    "turn": turn,
                })
            normalized["beats"] = beats
        return normalized

    if scope == "world" and isinstance(normalized.get("world"), dict):
        locations = normalized["world"].get("locations")
        if not isinstance(locations, list):
            return normalized
        for location in locations:
            if not isinstance(location, dict):
                continue
            name = str(location.get("name") or "this location").strip()
            description = str(
                location.get("description") or location.get("purpose") or ""
            ).strip()
            # These are presentation-only fields.  When an otherwise useful
            # location omits them, deterministic defaults are safer and
            # cheaper than throwing away the whole world and asking the LLM
            # to regenerate it.  The user can still edit both fields later.
            if not isinstance(location.get("visualPrompt"), str) or not location["visualPrompt"].strip():
                location["visualPrompt"] = " ".join(part for part in (
                    name,
                    description,
                    "single coherent environment concept art, no text or labels",
                ) if part)
            if not isinstance(location.get("negativePrompt"), str) or not location["negativePrompt"].strip():
                location["negativePrompt"] = (
                    "text, lettering, captions, logos, UI, collage, contact sheet, grid"
                )
        return normalized

    if scope == "characters" and isinstance(normalized.get("characters"), list):
        used: set[str] = set()
        for index, character in enumerate(normalized["characters"]):
            if not isinstance(character, dict):
                continue
            candidate = str(character.get("id") or "").strip()
            if not candidate:
                candidate = _story_id_token(character.get("name")) or f"character-{index + 1}"
            base = candidate
            suffix = 2
            while candidate in used:
                candidate = f"{base}-{suffix}"
                suffix += 1
            character["id"] = candidate
            used.add(candidate)
        return normalized

    if scope == "music" and isinstance(normalized, dict):
        # Keep a useful song when a provider returns the right content under
        # a harmless wrapper alias (or returns the single music-video cue as
        # the music object itself).  This also lets us repair small internal
        # contradictions before a schema-repair call can discard the song.
        raw_music = normalized.get("music")
        if isinstance(raw_music, list):
            music = {"cues": raw_music}
        elif isinstance(raw_music, dict):
            music = raw_music
        else:
            music = {}

        cues = music.get("cues")
        if not isinstance(cues, list):
            cues = next((
                music.get(key)
                for key in ("songs", "tracks", "proposals", "items")
                if isinstance(music.get(key), list)
            ), None)
        if not isinstance(cues, list):
            single = next((
                music.get(key)
                for key in ("song", "track", "cue")
                if isinstance(music.get(key), dict)
            ), None)
            if single is None and any(
                key in music
                for key in ("lyrics", "songLyrics", "song_lyrics", "style", "musicStyle")
            ):
                single = music
            if isinstance(single, dict):
                cues = [single]
        if not isinstance(cues, list):
            cues = next((
                normalized.get(key)
                for key in ("cues", "songs", "tracks", "proposals")
                if isinstance(normalized.get(key), list)
            ), None)
        if not isinstance(cues, list):
            return normalized
        normalized["music"] = {"cues": cues}

        project_type = str(project.get("projectType") or "full_story").strip().lower()
        creative_brief = (
            project.get("creativeBrief")
            if isinstance(project.get("creativeBrief"), dict)
            else {}
        )
        project_music = (
            project.get("music") if isinstance(project.get("music"), dict) else {}
        )

        def cue_text(cue: dict, *keys: str) -> str:
            for key in keys:
                value = cue.get(key)
                if isinstance(value, str) and value.strip():
                    return value.strip()
            return ""

        def cue_lyrics(cue: dict) -> str:
            value = next((
                cue.get(key)
                for key in ("lyrics", "songLyrics", "song_lyrics", "text")
                if cue.get(key) not in (None, "")
            ), "")
            if isinstance(value, list):
                return "\n".join(str(line).strip() for line in value if str(line).strip())
            if isinstance(value, dict):
                tags = {
                    "intro": "Intro", "verse": "Verse", "verse1": "Verse",
                    "verse2": "Verse", "prechorus": "Pre Chorus",
                    "chorus": "Chorus", "hook": "Hook", "bridge": "Bridge",
                    "outro": "Outro",
                }
                sections = []
                for key, lines in value.items():
                    text = (
                        "\n".join(str(line).strip() for line in lines if str(line).strip())
                        if isinstance(lines, list) else str(lines or "").strip()
                    )
                    if not text:
                        continue
                    token = re.sub(r"[^a-z0-9]+", "", str(key).casefold())
                    sections.append(f"[{tags.get(token, 'Verse')}]\n\n{text}")
                return "\n\n".join(sections)
            return str(value or "").strip()

        characters = [
            character for character in project.get("characters", [])
            if isinstance(character, dict) and str(character.get("id") or "").strip()
        ]
        character_lookup = {}
        for character in characters:
            canonical = str(character["id"]).strip()
            for alias in (character.get("id"), character.get("name")):
                token = _story_id_token(alias)
                if token:
                    character_lookup[token] = canonical
        used: set[str] = set()
        for index, cue in enumerate(cues):
            if not isinstance(cue, dict):
                continue
            kind = str(cue.get("kind") or "").strip().lower()
            target = str(cue.get("targetId") or "").strip()
            if project_type == "music_video":
                # A non-empty lyrics field is authoritative for a vocal song;
                # providers sometimes copy an instrumental default despite
                # the explicit music-video contract.
                kind = "story"
                target = "story"
                cue["kind"] = kind
                cue["targetId"] = target
                cue["title"] = cue_text(cue, "title", "name", "songTitle", "song_title") or (
                    str(project.get("title") or "Main story song").strip()
                )
                story_direction = str(
                    creative_brief.get("songStory")
                    or project_music.get("brief")
                    or project.get("premise")
                    or "This song drives the visual story."
                ).strip()
                cue["purpose"] = cue_text(
                    cue, "purpose", "goal", "concept", "description"
                ) or story_direction
                cue["brief"] = cue_text(
                    cue, "brief", "description", "prompt", "songBrief", "song_brief"
                ) or story_direction
                cue["referenceSong"] = cue_text(
                    cue, "referenceSong", "reference_song", "reference", "inspiration"
                ) or "Original composition — No direct reference"
                style = cue_text(
                    cue, "style", "musicStyle", "music_style", "stylePrompt", "style_prompt"
                ) or str(
                    creative_brief.get("musicStyle")
                    or project_music.get("style")
                    or "cinematic story song, expressive lead vocal, dynamic original production"
                ).strip()
                cue["style"] = style[:300]
                lyrics = cue_lyrics(cue)[:3500].strip()
                if lyrics and not re.search(
                    r"^\[(Verse|Chorus|Hook)\]\s*$", lyrics, re.MULTILINE
                ):
                    if "\n" not in lyrics and "/" in lyrics:
                        lyrics = re.sub(r"\s*/\s*", "\n", lyrics)
                    lyrics = f"[Verse]\n\n{lyrics}"[:3500].rstrip()
                cue["lyrics"] = lyrics
                cue["instrumental"] = False
                requested_duration = creative_brief.get(
                    "durationSeconds", project_music.get("targetDurationSeconds")
                )
                duration = (
                    requested_duration
                    if requested_duration not in (None, "")
                    else cue.get("durationSeconds", cue.get("duration_seconds"))
                )
                if isinstance(duration, bool):
                    duration = None
                try:
                    duration = int(float(duration))
                except (TypeError, ValueError):
                    duration = creative_brief.get(
                        "durationSeconds", project_music.get("targetDurationSeconds", 90)
                    )
                    try:
                        duration = int(float(duration))
                    except (TypeError, ValueError):
                        duration = 90
                cue["durationSeconds"] = max(20, min(360, duration))
            elif kind == "character":
                target = character_lookup.get(_story_id_token(target), target)
            elif kind == "world":
                target = "world"
            cue["targetId"] = target
            candidate = _story_id_token(cue.get("id")) or f"music-{kind or 'cue'}-{index + 1}"
            base = candidate
            suffix = 2
            while candidate in used:
                candidate = f"{base}-{suffix}"
                suffix += 1
            cue["id"] = candidate
            used.add(candidate)
        return normalized

    if scope != "relationships" or not isinstance(normalized.get("relationships"), list):
        return normalized
    characters = [
        character for character in project.get("characters", [])
        if isinstance(character, dict) and str(character.get("id") or "").strip()
    ]
    canonical_ids = {str(character["id"]).strip() for character in characters}
    lookup: dict[str, str] = {}
    for character in characters:
        canonical = str(character["id"]).strip()
        for alias in (character.get("id"), character.get("name")):
            stripped = str(alias or "").strip()
            if stripped:
                lookup.setdefault(stripped.casefold(), canonical)
                token = _story_id_token(stripped)
                if token:
                    lookup.setdefault(token, canonical)

    def resolve(value) -> str:
        stripped = str(value or "").strip()
        if stripped in canonical_ids:
            return stripped
        return lookup.get(stripped.casefold()) or lookup.get(_story_id_token(stripped)) or stripped

    relationships = []
    used_ids: set[str] = set()
    for index, relationship in enumerate(normalized["relationships"]):
        if not isinstance(relationship, dict):
            relationships.append(relationship)
            continue
        relationship["fromCharacterId"] = resolve(relationship.get("fromCharacterId"))
        relationship["toCharacterId"] = resolve(relationship.get("toCharacterId"))
        relation_id = str(relationship.get("id") or "").strip()
        if not relation_id:
            relation_id = f"relationship-{index + 1}"
        base = relation_id
        suffix = 2
        while relation_id in used_ids:
            relation_id = f"{base}-{suffix}"
            suffix += 1
        relationship["id"] = relation_id
        used_ids.add(relation_id)
        valid = (
            relationship["fromCharacterId"] in canonical_ids
            and relationship["toCharacterId"] in canonical_ids
            and relationship["fromCharacterId"] != relationship["toCharacterId"]
        )
        if valid or not drop_unknown_relationships:
            relationships.append(relationship)
    normalized["relationships"] = relationships
    return normalized


def _story_stage_problem(result: dict, scope: str, project: dict) -> str | None:
    project_type = str(project.get("projectType") or "full_story").strip().lower()
    if not isinstance(result, dict):
        return "response root is not a JSON object"
    key = "beats" if scope == "structure" else scope
    value = result.get(key)
    if scope in {"overview", "world", "music"} and not isinstance(value, dict):
        return f"{key} is not an object"
    if scope in {"characters", "relationships", "structure"} and not isinstance(value, list):
        return f"{key} is not an array"
    required = {
        "overview": {
            "title", "creativeBrief", "language", "genre", "tone", "audience",
            "visualStyle", "characterVisualStyle", "enforceVisualStyle",
            "allowClipText", "musicVideoGenerationMode", "premise", "logline",
            "synopsis", "theme", "ending",
        },
        "world": {
            "summary", "period", "geography", "society", "technology", "rules",
            "visualLanguage", "visualPrompt", "negativePrompt", "locations",
        },
        "characters": {
            "id", "name", "role", "age", "pronouns", "personality", "desire",
            "need", "flaw", "conflict", "arc", "voice", "appearance", "wardrobe",
            "visualPrompt", "negativePrompt",
        },
        "relationships": {
            "id", "fromCharacterId", "toCharacterId", "label", "dynamic", "evolution",
        },
        "structure": {"id", "stage", "title", "summary", "goal", "conflict", "turn"},
    }
    if scope == "overview":
        missing = required["overview"] - set(value)
        if missing:
            return f"overview is missing {', '.join(sorted(missing))}"
        string_fields = required["overview"] - {
            "creativeBrief", "enforceVisualStyle", "allowClipText",
        }
        for field in string_fields:
            if not isinstance(value.get(field), str):
                return f"overview field {field} is not a string"
        if not isinstance(value.get("enforceVisualStyle"), bool) or not isinstance(value.get("allowClipText"), bool):
            return "overview style/text flags must be boolean"
        generated_brief = value.get("creativeBrief")
        if not isinstance(generated_brief, dict):
            return "overview creativeBrief is not an object"
        brief_fields = {
            "generalIdea", "context", "performer", "musicStyle", "songStory",
            "subjects", "setting", "action", "quickFormat", "durationSeconds",
        }
        brief_missing = brief_fields - set(generated_brief)
        if brief_missing:
            return f"overview creativeBrief is missing {', '.join(sorted(brief_missing))}"
        if any(not isinstance(generated_brief.get(field), str) for field in brief_fields - {"durationSeconds"}):
            return "overview creativeBrief contains a non-string field"
        duration = generated_brief.get("durationSeconds")
        if not isinstance(duration, int) or isinstance(duration, bool) or not 5 <= duration <= 360:
            return "overview creativeBrief durationSeconds is outside 5–360"
        return None
    if scope == "world":
        missing = required["world"] - set(value)
        if missing:
            return f"world is missing {', '.join(sorted(missing))}"
        if not isinstance(value.get("rules"), list) or not isinstance(value.get("locations"), list):
            return "world rules and locations must be arrays"
        if len(value["rules"]) > 12 or not all(isinstance(item, str) for item in value["rules"]):
            return "world rules must contain at most twelve strings"
        if len(value["locations"]) > 8:
            return "world has more than eight locations"
        for field in required["world"] - {"rules", "locations"}:
            if not isinstance(value.get(field), str):
                return f"world field {field} is not a string"
        for index, location in enumerate(value["locations"]):
            if not isinstance(location, dict):
                return f"location {index + 1} is not an object"
            location_missing = {
                "id", "name", "purpose", "description", "visualPrompt", "negativePrompt",
            } - set(location)
            if location_missing:
                return (
                    f"location {index + 1} is missing "
                    f"{', '.join(sorted(location_missing))}"
                )
            for field in {
                "id", "name", "purpose", "description", "visualPrompt", "negativePrompt",
            }:
                if not isinstance(location.get(field), str):
                    return f"location {index + 1} field {field} is not a string"
        return None
    if scope == "music":
        cues = value.get("cues")
        if not isinstance(cues, list):
            return "music cues is not an array"
        character_ids = {
            str(item.get("id") or "").strip()
            for item in project.get("characters", []) if isinstance(item, dict)
        }
        expected_count = 1 if project_type == "music_video" else len(character_ids) + 4
        if len(cues) != expected_count:
            return f"music must contain exactly {expected_count} cues"
        required_cue = {
            "id", "kind", "targetId", "title", "purpose", "referenceSong",
            "brief", "style", "lyrics", "instrumental", "durationSeconds",
        }
        ids = []
        for index, cue in enumerate(cues):
            if not isinstance(cue, dict):
                return f"music cue {index + 1} is not an object"
            missing = required_cue - set(cue)
            if missing:
                return f"music cue {index + 1} is missing {', '.join(sorted(missing))}"
            for field in required_cue - {"instrumental", "durationSeconds"}:
                if not isinstance(cue.get(field), str):
                    return f"music cue {index + 1} field {field} is not a string"
            if not isinstance(cue.get("instrumental"), bool):
                return f"music cue {index + 1} instrumental is not a boolean"
            duration = cue.get("durationSeconds")
            if not isinstance(duration, int) or isinstance(duration, bool) or not 20 <= duration <= 360:
                return f"music cue {index + 1} durationSeconds is outside 20–360"
            style = cue["style"].strip()
            lyrics = cue["lyrics"].strip()
            if not 10 <= len(style) <= 300:
                return f"music cue {index + 1} style must contain 10–300 characters"
            if not cue["referenceSong"].strip():
                return f"music cue {index + 1} needs an editable reference song"
            if cue["instrumental"] and lyrics:
                return f"instrumental music cue {index + 1} must have empty lyrics"
            if not cue["instrumental"]:
                if not 10 <= len(lyrics) <= 3500:
                    return f"vocal music cue {index + 1} lyrics must contain 10–3500 characters"
                if not re.search(r"^\[(Verse|Chorus|Hook)\]\s*$", lyrics, re.MULTILINE):
                    return f"vocal music cue {index + 1} needs supported structural tags"
            ids.append(cue["id"])
        if len(ids) != len(set(ids)):
            return "music contains duplicate IDs"
        if project_type == "music_video":
            cue = cues[0]
            if cue["kind"] != "story" or cue["targetId"] != "story":
                return "music-video mode needs one story song"
            if cue["instrumental"]:
                return "the music-video song must include vocals"
            return None
        world_cues = [cue for cue in cues if cue["kind"] == "world" and cue["targetId"] == "world"]
        character_targets = {
            cue["targetId"] for cue in cues if cue["kind"] == "character"
        }
        story_cues = [cue for cue in cues if cue["kind"] == "story"]
        if len(world_cues) != 1:
            return "music needs exactly one world ambience cue"
        if not world_cues[0]["instrumental"]:
            return "the world ambience cue must be instrumental"
        if character_targets != character_ids or len(character_targets) != len([
            cue for cue in cues if cue["kind"] == "character"
        ]):
            return "music needs exactly one presentation cue per character ID"
        if len(story_cues) != 3:
            return "music needs exactly three story songs"
        if any(cue["instrumental"] for cue in story_cues):
            return "the three story songs must include vocals"
        return None
    if not value and scope != "relationships":
        return f"{key} is empty"
    limits = {
        "characters": (1, 12),
        "relationships": (0, 24),
        "structure": (
            (3, 8) if project_type == "quick_video"
            else (4, 10) if project_type == "music_video"
            else (6, 12) if project_type == "trailer"
            else (6, 14)
        ),
    }
    minimum, maximum = limits[scope]
    if len(value) < minimum or len(value) > maximum:
        return f"{key} must contain between {minimum} and {maximum} items"
    item_required = required[scope]
    for index, item in enumerate(value):
        if not isinstance(item, dict):
            return f"{key} item {index + 1} is not an object"
        missing = item_required - set(item)
        if missing:
            return f"{key} item {index + 1} is missing {', '.join(sorted(missing))}"
        for field in item_required:
            if not isinstance(item.get(field), str):
                return f"{key} item {index + 1} field {field} is not a string"
    ids = [item.get("id") for item in value]
    if len(ids) != len(set(ids)):
        return f"{key} contains duplicate IDs"
    if scope == "relationships":
        character_ids = {
            str(item.get("id") or "") for item in project.get("characters", [])
            if isinstance(item, dict)
        }
        for item in value:
            if (
                item.get("fromCharacterId") not in character_ids
                or item.get("toCharacterId") not in character_ids
            ):
                return "a relationship references an unknown character ID"
    return None


def _story_project_prompt_context(project: dict, scope: str) -> str:
    """Return bounded, valid JSON with editorial facts but no heavy runtime data."""
    overview_keys = (
        "title", "projectType", "creativeBrief", "language", "spokenLanguage", "locationVariety",
        "protagonistConsistency", "protagonistCharacterId", "genre", "tone", "audience", "premise",
        "logline", "synopsis", "theme", "ending", "visualStyle",
        "characterVisualStyle", "enforceVisualStyle", "allowClipText",
    )
    compact = {key: project.get(key) for key in overview_keys if key in project}
    # Characters are useful grounding for every downstream phase and are
    # required for relationship IDs. The active section keeps its full facts;
    # other stages only need a concise identity summary.
    raw_characters = project.get("characters")
    if isinstance(raw_characters, list):
        if scope == "characters":
            compact["characters"] = raw_characters
        else:
            compact["characters"] = [
                {
                    key: item.get(key)
                    for key in ("id", "name", "role", "personality", "desire", "arc", "appearance")
                    if key in item
                }
                for item in raw_characters if isinstance(item, dict)
            ]
    if scope in {"world", "relationships", "structure", "music"} and isinstance(project.get("world"), dict):
        compact["world"] = project["world"]
    if scope in {"relationships", "structure", "music"} and isinstance(project.get("relationships"), list):
        compact["relationships"] = project["relationships"]
    if scope in {"structure", "music"} and isinstance(project.get("beats"), list):
        compact["beats"] = project["beats"]

    def bounded(value, string_limit: int):
        if isinstance(value, str):
            return value if len(value) <= string_limit else value[:string_limit] + "…"
        if isinstance(value, list):
            return [bounded(item, string_limit) for item in value[:24]]
        if isinstance(value, dict):
            return {
                str(key): bounded(item, string_limit)
                for key, item in value.items()
                if key not in {
                    "assets", "productions", "approvals", "sectionVersions",
                    "visualJobs", "packedAssets", "approval",
                }
            }
        if value is None or isinstance(value, (bool, int, float)):
            return value
        return str(value)

    bounded_context = bounded(compact, 2000)
    encoded = json.dumps(bounded_context, ensure_ascii=False)
    if len(encoded) > 24000:
        encoded = json.dumps(bounded(compact, 600), ensure_ascii=False)
    return encoded


def _story_checkpoint_request(body: dict) -> dict:
    """Keep durable writing checkpoints small and free of editor/runtime history."""
    request = copy.deepcopy(body)
    project = request.get("project")
    if isinstance(project, dict):
        for key in (
            "assets", "productions", "approvals", "sectionVersions",
            "visualJobs", "packedAssets",
        ):
            project.pop(key, None)
        for character in project.get("characters", []):
            if isinstance(character, dict):
                character.pop("referenceAssetIds", None)
                character.pop("primaryReferenceAssetId", None)
                character.pop("approval", None)
        world = project.get("world")
        if isinstance(world, dict):
            world.pop("referenceAssetIds", None)
            for location in world.get("locations", []):
                if isinstance(location, dict):
                    location.pop("referenceAssetIds", None)
        music = project.get("music")
        if isinstance(music, dict):
            music.pop("candidates", None)
            music.pop("selectedCandidateId", None)
            music.pop("coverReferenceFilename", None)
            for cue in music.get("cues", []):
                if isinstance(cue, dict):
                    cue.pop("candidates", None)
                    cue.pop("selectedCandidateId", None)
    return request


def _story_resume_request(request: dict, override: dict | None) -> dict:
    """Apply an explicit current writing profile to a durable resume request."""
    updated = copy.deepcopy(request)
    if not isinstance(override, dict):
        return updated
    provider = str(override.get("writingProvider") or "").strip()
    if not provider:
        return updated
    updated["writingProvider"] = provider
    updated["writingModel"] = str(override.get("writingModel") or "").strip()
    updated["writingBaseUrl"] = str(override.get("writingBaseUrl") or "").strip()
    project = updated.get("project")
    if isinstance(project, dict):
        profile = project.get("provider") if isinstance(project.get("provider"), dict) else {}
        project["provider"] = {
            **profile,
            "writingProvider": updated["writingProvider"],
            "writingModel": updated["writingModel"],
            "writingBaseUrl": updated["writingBaseUrl"],
        }
    return updated


_series_library_lock = threading.RLock()


def _series_library_workspace(value) -> str:
    from services.series_library import validate_workspace_id

    try:
        return validate_workspace_id(value or _get_active_workspace())
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc


def _read_series_workspace(workspace: str) -> dict:
    from services.series_library import read_series_library

    return read_series_library(_workspace_dir(workspace), workspace)


def _write_series_workspace(workspace: str, library: dict) -> dict:
    from services.series_library import write_series_library

    return write_series_library(_workspace_dir(workspace), library, workspace)


def _series_project_or_404(library: dict, series_id: str) -> dict:
    series = library.get("seriesById", {}).get(series_id)
    if not isinstance(series, dict):
        raise HTTPException(status_code=404, detail="Series Lab project not found")
    return series


def _require_series_deletion_ready(
    workspace: str,
    series_id: str,
    episode_id: str | None = None,
) -> None:
    from services.series_lifecycle import ActiveSeriesJobsError, require_no_active_series_jobs

    try:
        require_no_active_series_jobs(
            _workspace_dir(workspace),
            workspace,
            series_id,
            episode_id=episode_id,
        )
    except ActiveSeriesJobsError as exc:
        raise HTTPException(status_code=409, detail=exc.detail()) from exc


@api.get("/api/v1/series/library")
def get_series_library(workspace: str | None = None):
    """Load the authoritative Series Lab library for one workspace."""
    target_workspace = _series_library_workspace(workspace)
    try:
        with _series_library_lock:
            return _read_series_workspace(target_workspace)
    except (OSError, ValueError, json.JSONDecodeError) as exc:
        raise HTTPException(status_code=500, detail=f"Could not read the Series Lab library: {exc}") from exc


@api.put("/api/v1/series/library")
def put_series_library(body: dict):
    """Atomically replace a Series library; resource endpoints are preferred."""
    target_workspace = _series_library_workspace(body.get("workspace"))
    try:
        with _series_library_lock:
            return _write_series_workspace(target_workspace, body.get("library"))
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    except OSError as exc:
        raise HTTPException(status_code=500, detail=f"Could not save the Series Lab library: {exc}") from exc


@api.get("/api/v1/series")
def list_series_projects(workspace: str | None = None):
    target_workspace = _series_library_workspace(workspace)
    with _series_library_lock:
        library = _read_series_workspace(target_workspace)
    return {
        "workspaceId": target_workspace,
        "seriesOrder": library["seriesOrder"],
        "series": [library["seriesById"][item] for item in library["seriesOrder"]],
    }


@api.post("/api/v1/series")
def create_series_project_endpoint(body: dict):
    from services.series_library import create_series_project, normalize_series_project

    workspace = _series_library_workspace(body.get("workspace"))
    try:
        with _series_library_lock:
            library = _read_series_workspace(workspace)
            raw_series = body.get("series")
            series = (
                normalize_series_project(raw_series, str(raw_series.get("id") or ""), workspace)
                if isinstance(raw_series, dict)
                else create_series_project(workspace, title=str(body.get("title") or "Untitled series"))
            )
            if series["id"] in library["seriesById"]:
                raise HTTPException(status_code=409, detail="A Series Lab project with this id already exists")
            library["seriesById"][series["id"]] = series
            library["seriesOrder"].append(series["id"])
            stored = _write_series_workspace(workspace, library)
            return stored["seriesById"][series["id"]]
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc


@api.get("/api/v1/series/{series_id}")
def get_series_project_endpoint(series_id: str, workspace: str | None = None):
    target_workspace = _series_library_workspace(workspace)
    with _series_library_lock:
        return _series_project_or_404(_read_series_workspace(target_workspace), series_id)


@api.put("/api/v1/series/{series_id}")
def put_series_project_endpoint(series_id: str, body: dict):
    from services.series_library import normalize_series_project

    workspace = _series_library_workspace(body.get("workspace"))
    raw_series = body.get("series")
    if not isinstance(raw_series, dict):
        raise HTTPException(status_code=400, detail="Series project is required")
    if raw_series.get("id") not in {None, "", series_id}:
        raise HTTPException(status_code=400, detail="Series project id does not match the route")
    try:
        with _series_library_lock:
            library = _read_series_workspace(workspace)
            current = _series_project_or_404(library, series_id)
            base_revision = body.get("baseRevision")
            if base_revision is not None and int(base_revision) != int(current.get("revision") or 1):
                raise HTTPException(
                    status_code=409,
                    detail=f"Series revision changed to {current.get('revision')}; reload before saving",
                )
            updated = normalize_series_project({**raw_series, "id": series_id}, series_id, workspace)
            canon_inputs = (
                "title", "premise", "logline", "format", "language", "spokenLanguage",
                "protagonistConsistency", "protagonistCharacterId", "genre", "tone", "audience",
                "visualStyle", "characterVisualStyle", "cameraLanguage", "sourceMode",
                "masterUniversePrompt", "characters", "relationships", "locations", "props",
            )
            current_canon = copy.deepcopy(current.get("canon") or {})
            updated_canon = copy.deepcopy(updated.get("canon") or {})
            for value in (current_canon, updated_canon):
                value.pop("approval", None); value.pop("approvedAt", None)
            if current_canon != updated_canon or any(
                current.get(key) != updated.get(key) for key in canon_inputs
            ):
                updated["canon"]["approval"] = "draft"
                updated["canon"]["approvedAt"] = ""
            updated["revision"] = int(current.get("revision") or 1) + 1
            updated["createdAt"] = current.get("createdAt") or updated["createdAt"]
            updated["updatedAt"] = datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")
            library["seriesById"][series_id] = updated
            stored = _write_series_workspace(workspace, library)
            return stored["seriesById"][series_id]
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc


@api.delete("/api/v1/series/{series_id}")
def delete_series_project_endpoint(series_id: str, workspace: str | None = None):
    target_workspace = _series_library_workspace(workspace)
    with _series_library_lock:
        library = _read_series_workspace(target_workspace)
        _series_project_or_404(library, series_id)
        _require_series_deletion_ready(target_workspace, series_id)
        del library["seriesById"][series_id]
        library["seriesOrder"] = [item for item in library["seriesOrder"] if item != series_id]
        _write_series_workspace(target_workspace, library)
    return {"deleted": True, "seriesId": series_id, "outputsPreserved": True}


@api.post("/api/v1/series/{series_id}/duplicate")
def duplicate_series_project_endpoint(series_id: str, body: dict | None = None):
    from services.series_library import duplicate_series_project, normalize_series_project

    body = body if isinstance(body, dict) else {}
    workspace = _series_library_workspace(body.get("workspace"))
    with _series_library_lock:
        library = _read_series_workspace(workspace)
        source = _series_project_or_404(library, series_id)
        duplicate = duplicate_series_project(source)
        duplicate = normalize_series_project(duplicate, duplicate["id"], workspace)
        library["seriesById"][duplicate["id"]] = duplicate
        source_index = library["seriesOrder"].index(series_id)
        library["seriesOrder"].insert(source_index + 1, duplicate["id"])
        stored = _write_series_workspace(workspace, library)
    return stored["seriesById"][duplicate["id"]]


@api.post("/api/v1/series/import-story")
def import_story_as_series_endpoint(body: dict):
    from services.series_library import import_story_project
    from services.story_library import read_story_library
    import shutil

    workspace = _series_library_workspace(body.get("workspace"))
    story = body.get("story") if isinstance(body.get("story"), dict) else None
    if story is None:
        story_id = str(body.get("storyId") or "").strip()
        if not story_id:
            raise HTTPException(status_code=400, detail="Choose a Story Lab project to import")
        story_library = read_story_library(_workspace_dir(workspace))
        story = story_library.get("projects", {}).get(story_id)
        if not isinstance(story, dict):
            raise HTTPException(status_code=404, detail="Story Lab source project not found")
    try:
        story_for_import = copy.deepcopy(story)
        upload_sources: dict[str, str] = {}
        for asset_key, asset in (
            story_for_import.get("assets", {}).items()
            if isinstance(story_for_import.get("assets"), dict) else []
        ):
            if not isinstance(asset, dict):
                continue
            source = str(asset.get("source") or "")
            if source.startswith("/api/v1/uploads/"):
                from urllib.parse import unquote
                upload_name = unquote(source.split("/api/v1/uploads/", 1)[1])
                local_candidate = _safe_join(os.path.join(os.getcwd(), "uploads"), upload_name)
                local_source = _story_import_upload_path(local_candidate or "")
                asset_id = str(asset.get("id") or asset_key)
                upload_sources[asset_id] = local_source
                # A valid workspace placeholder lets the pure importer retain
                # entity links. It is replaced with the copied destination
                # before the authoritative library is written.
                asset["source"] = f"assets/story-import/{uuid.uuid4().hex}.bin"
            elif os.path.isabs(source):
                try:
                    local_source = _story_import_upload_path(source)
                except HTTPException:
                    continue
                asset_id = str(asset.get("id") or asset_key)
                upload_sources[asset_id] = local_source
                # A valid workspace placeholder lets the pure importer retain
                # entity links. It is replaced with the copied destination
                # before the authoritative library is written.
                asset["source"] = f"assets/story-import/{uuid.uuid4().hex}.bin"
        imported = import_story_project(story_for_import, workspace)
        for asset_id, local_source in upload_sources.items():
            imported_asset = imported.get("assets", {}).get(asset_id)
            if not isinstance(imported_asset, dict):
                continue
            extension = os.path.splitext(local_source)[1].lower()[:12]
            relative = f"assets/{imported['id']}/{uuid.uuid4().hex[:16]}{extension}"
            destination = _safe_join(_workspace_dir(workspace), relative)
            if not destination:
                raise ValueError("Invalid imported Story asset destination")
            os.makedirs(os.path.dirname(destination), exist_ok=True)
            shutil.copy2(local_source, destination)
            imported_asset["uri"] = relative
        with _series_library_lock:
            library = _read_series_workspace(workspace)
            library["seriesById"][imported["id"]] = imported
            library["seriesOrder"].append(imported["id"])
            stored = _write_series_workspace(workspace, library)
        return stored["seriesById"][imported["id"]]
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc


@api.post("/api/v1/series/{series_id}/episodes")
def create_series_episode_endpoint(series_id: str, body: dict):
    from services.series_library import create_series_episode

    workspace = _series_library_workspace(body.get("workspace"))
    with _series_library_lock:
        library = _read_series_workspace(workspace)
        series = copy.deepcopy(_series_project_or_404(library, series_id))
        if series.get("canon", {}).get("approval") != "approved":
            raise HTTPException(status_code=400, detail="Approve the reviewed Series canon before creating an episode")
        episode = create_series_episode(
            series, str(body.get("seasonId") or "") or None,
            **(body.get("episode") if isinstance(body.get("episode"), dict) else {}),
        )
        series["episodesById"][episode["id"]] = episode
        season = next(item for item in series["seasons"] if item["id"] == episode["seasonId"])
        season["episodeOrder"].append(episode["id"])
        series["revision"] = int(series.get("revision") or 1) + 1
        series["updatedAt"] = episode["updatedAt"]
        library["seriesById"][series_id] = series
        stored = _write_series_workspace(workspace, library)
    return stored["seriesById"][series_id]["episodesById"][episode["id"]]


@api.get("/api/v1/series/{series_id}/episodes")
def list_series_episodes_endpoint(series_id: str, workspace: str | None = None):
    target_workspace = _series_library_workspace(workspace)
    with _series_library_lock:
        series = _series_project_or_404(_read_series_workspace(target_workspace), series_id)
        ordered = []
        seen: set[str] = set()
        for season in series.get("seasons", []):
            if not isinstance(season, dict):
                continue
            for episode_id in season.get("episodeOrder", []):
                episode = series.get("episodesById", {}).get(episode_id)
                if isinstance(episode, dict) and episode_id not in seen:
                    ordered.append(copy.deepcopy(episode)); seen.add(episode_id)
        ordered.extend(
            copy.deepcopy(episode) for episode_id, episode in series.get("episodesById", {}).items()
            if isinstance(episode, dict) and episode_id not in seen
        )
    return {"episodes": ordered}


@api.get("/api/v1/series/{series_id}/episodes/{episode_id}")
def get_series_episode_endpoint(series_id: str, episode_id: str, workspace: str | None = None):
    target_workspace = _series_library_workspace(workspace)
    with _series_library_lock:
        series = _series_project_or_404(_read_series_workspace(target_workspace), series_id)
        episode = series.get("episodesById", {}).get(episode_id)
        if not isinstance(episode, dict):
            raise HTTPException(status_code=404, detail="Series episode not found")
        return copy.deepcopy(episode)


@api.delete("/api/v1/series/{series_id}/episodes/{episode_id}")
def delete_series_episode_endpoint(series_id: str, episode_id: str, workspace: str | None = None):
    target_workspace = _series_library_workspace(workspace)
    with _series_library_lock:
        library = _read_series_workspace(target_workspace)
        series = copy.deepcopy(_series_project_or_404(library, series_id))
        if episode_id not in series.get("episodesById", {}):
            raise HTTPException(status_code=404, detail="Series episode not found")
        _require_series_deletion_ready(target_workspace, series_id, episode_id)
        del series["episodesById"][episode_id]
        for season in series.get("seasons", []):
            if isinstance(season, dict):
                season["episodeOrder"] = [item for item in season.get("episodeOrder", []) if item != episode_id]
        now = _series_iso_now()
        series["revision"] = int(series.get("revision") or 1) + 1
        series["updatedAt"] = now
        library["seriesById"][series_id] = series
        _write_series_workspace(target_workspace, library)
    return {"deleted": True, "episodeId": episode_id, "outputsPreserved": True}


@api.post("/api/v1/series/{series_id}/assets/import")
def import_series_asset_endpoint(series_id: str, body: dict):
    """Copy a Maestro upload into the authoritative workspace asset tree."""
    import shutil

    workspace = _series_library_workspace(body.get("workspace"))
    source = _story_import_upload_path(str(body.get("uploadPath") or ""))
    owner_type = str(body.get("ownerType") or "series")
    owner_id = str(body.get("ownerId") or series_id).strip()
    if owner_type not in {"series", "character", "location", "prop", "episode", "shot"}:
        raise HTTPException(status_code=400, detail="Unsupported Series asset owner")
    kind = str(body.get("kind") or "image")
    if kind not in {"image", "audio", "video", "character", "location", "prop", "other"}:
        kind = "other"
    extension = os.path.splitext(source)[1].lower()[:12]
    extra_metadata = copy.deepcopy(body.get("metadata")) if isinstance(body.get("metadata"), dict) else {}
    if len(json.dumps(extra_metadata, ensure_ascii=False, default=str).encode("utf-8")) > 32 * 1024:
        raise HTTPException(status_code=413, detail="Series asset metadata is too large")
    asset_id = f"asset_{uuid.uuid4().hex[:12]}"
    relative = os.path.join("assets", series_id, f"{asset_id}{extension}").replace(os.sep, "/")
    destination = _safe_join(_workspace_dir(workspace), relative)
    if not destination:
        raise HTTPException(status_code=400, detail="Invalid Series asset destination")
    with _series_library_lock:
        library = _read_series_workspace(workspace)
        series = copy.deepcopy(_series_project_or_404(library, series_id))
        entity = None
        collection_name = {
            "character": "characters", "location": "locations", "prop": "props",
        }.get(owner_type)
        if collection_name:
            entity = next((
                item for item in series.get(collection_name, []) if item.get("id") == owner_id
            ), None)
            if not isinstance(entity, dict):
                raise HTTPException(status_code=404, detail=f"Series {owner_type} not found")
        elif owner_type == "episode" and owner_id not in series.get("episodesById", {}):
            raise HTTPException(status_code=404, detail="Series episode not found")
        elif owner_type == "shot" and not any(
            shot.get("id") == owner_id
            for episode in series.get("episodesById", {}).values() if isinstance(episode, dict)
            for shot in episode.get("shots", []) if isinstance(shot, dict)
        ):
            raise HTTPException(status_code=404, detail="Series shot not found")
        os.makedirs(os.path.dirname(destination), exist_ok=True)
        shutil.copy2(source, destination)
        asset = {
            "id": asset_id, "workspaceId": workspace, "kind": kind,
            "uri": relative, "ownerType": owner_type, "ownerId": owner_id,
            "isDerivedThumbnail": False,
            "metadata": {
                "name": str(body.get("name") or os.path.basename(source))[:300],
                "referenceRole": str(body.get("referenceRole") or "reference")[:100],
                "importedAt": _series_iso_now(),
                **({
                    str(key)[:100]: copy.deepcopy(value)
                    for key, value in extra_metadata.items()
                    if isinstance(key, str) and key not in {"referenceRole", "importedAt"}
                }),
            },
        }
        series.setdefault("assets", {})[asset_id] = asset
        if entity is not None:
            refs = entity.get("referenceAssetIds") if isinstance(entity.get("referenceAssetIds"), list) else []
            entity["referenceAssetIds"] = [*refs, asset_id]
            if owner_type == "character" and not entity.get("primaryReferenceAssetId"):
                entity["primaryReferenceAssetId"] = asset_id
            entity["approval"] = "draft"
            series.setdefault("canon", {})["approval"] = "draft"
            series["canon"]["approvedAt"] = ""
        now = _series_iso_now()
        series["revision"] = int(series.get("revision") or 1) + 1
        series["updatedAt"] = now
        library["seriesById"][series_id] = series
        stored = _write_series_workspace(workspace, library)
    return {"asset": stored["seriesById"][series_id]["assets"][asset_id], "series": stored["seriesById"][series_id]}


@api.put("/api/v1/series/{series_id}/episodes/{episode_id}")
def put_series_episode_endpoint(series_id: str, episode_id: str, body: dict):
    from routers.series_episode import apply_series_episode_update

    workspace = _series_library_workspace(body.get("workspace"))
    with _series_library_lock:
        library = _read_series_workspace(workspace)
        series = _series_project_or_404(library, series_id)
        updated_series = apply_series_episode_update(
            series_id, episode_id, body, series, updated_at=_series_iso_now(),
        )
        library["seriesById"][series_id] = updated_series
        stored = _write_series_workspace(workspace, library)
    return stored["seriesById"][series_id]["episodesById"][episode_id]


@api.post("/api/v1/series/{series_id}/episodes/{episode_id}/canon/commit")
def commit_series_canon_endpoint(series_id: str, episode_id: str, body: dict):
    from services.series_library import SeriesConflictError, commit_canon_delta

    workspace = _series_library_workspace(body.get("workspace"))
    decisions = body.get("decisions") if isinstance(body.get("decisions"), dict) else {}
    try:
        base_revision = int(body.get("baseRevision"))
    except (TypeError, ValueError) as exc:
        raise HTTPException(status_code=400, detail="baseRevision is required") from exc
    try:
        with _series_library_lock:
            library = _read_series_workspace(workspace)
            series = _series_project_or_404(library, series_id)
            updated = commit_canon_delta(series, episode_id, decisions, base_revision)
            library["seriesById"][series_id] = updated
            stored = _write_series_workspace(workspace, library)
        return stored["seriesById"][series_id]
    except SeriesConflictError as exc:
        raise HTTPException(status_code=409, detail=str(exc)) from exc
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc


@api.post("/api/v1/series/{series_id}/canon/approve")
def approve_series_canon_endpoint(series_id: str, body: dict):
    workspace = _series_library_workspace(body.get("workspace"))
    try:
        base_revision = int(body.get("baseRevision"))
    except (TypeError, ValueError) as exc:
        raise HTTPException(status_code=400, detail="baseRevision is required") from exc
    with _series_library_lock:
        library = _read_series_workspace(workspace)
        series = copy.deepcopy(_series_project_or_404(library, series_id))
        canon = series.get("canon") if isinstance(series.get("canon"), dict) else {}
        if int(canon.get("revision") or 1) != base_revision:
            raise HTTPException(
                status_code=409,
                detail=f"Canon revision changed to {canon.get('revision')}; reload before approval",
            )
        if not str(canon.get("worldSummary") or "").strip():
            raise HTTPException(status_code=400, detail="Complete the World summary before approving canon")
        if not series.get("characters"):
            raise HTTPException(status_code=400, detail="Add at least one principal character before approving canon")
        if not series.get("locations"):
            raise HTTPException(status_code=400, detail="Add at least one canonical location before approving canon")
        now = _series_iso_now()
        if canon.get("approval") != "approved":
            canon["revision"] = base_revision + 1
        canon["approval"] = "approved"
        canon["approvedAt"] = now
        series["canon"] = canon
        for collection in ("characters", "locations", "props"):
            for item in series.get(collection, []):
                if isinstance(item, dict):
                    item["approval"] = "approved"
        series["revision"] = int(series.get("revision") or 1) + 1
        series["updatedAt"] = now
        library["seriesById"][series_id] = series
        stored = _write_series_workspace(workspace, library)
    return stored["seriesById"][series_id]


@api.post("/api/v1/series/{series_id}/episodes/{episode_id}/references/route")
def route_series_episode_references_endpoint(series_id: str, episode_id: str, body: dict):
    from services.series_library import series_for_episode_snapshot
    from services.series_reference_router import route_episode_references, route_shot_references

    workspace = _series_library_workspace(body.get("workspace"))
    with _series_library_lock:
        library = _read_series_workspace(workspace)
        series = _series_project_or_404(library, series_id)
        episode = series.get("episodesById", {}).get(episode_id)
        if not isinstance(episode, dict):
            raise HTTPException(status_code=404, detail="Series episode not found")
        routing_series = series_for_episode_snapshot(series, episode)
        shot_id = str(body.get("shotId") or "").strip()
        capabilities = body.get("capabilities") if isinstance(body.get("capabilities"), dict) else None
        if shot_id:
            shot = next((item for item in episode.get("shots", []) if item.get("id") == shot_id), None)
            if not isinstance(shot, dict):
                raise HTTPException(status_code=404, detail="Series shot not found")
            return {"shotId": shot_id, "manifest": route_shot_references(routing_series, episode, shot, capabilities)}
        return {"manifests": route_episode_references(routing_series, episode, capabilities)}


_series_plan_jobs: dict[str, dict] = {}
_series_plan_jobs_lock = threading.RLock()
_series_plan_active_jobs: set[str] = set()


def _llm_abort_outcome(exc: Exception) -> bool | None:
    """Return whether a cancellation closed the active provider response."""
    value = getattr(exc, "abort_supported", None)
    return bool(value) if isinstance(value, bool) else None


def _planning_cancel_message(subject: str, abort_supported: bool | None) -> str:
    if abort_supported is True:
        outcome = "the active LLM response was closed immediately"
    elif abort_supported is False:
        outcome = "the provider could not abort its active response, so it stopped at the next safe boundary"
    else:
        outcome = "the active request was aborted where supported and otherwise stopped at the next safe boundary"
    return f"{subject} cancelled: {outcome}. Completed stages remain recoverable."


def _series_plan_store(workspace: str):
    from services.series_jobs import SeriesJobStore

    return SeriesJobStore(_workspace_dir(workspace), "planning")


def _load_series_plan_job(job_id: str) -> dict | None:
    with _series_plan_jobs_lock:
        cached = _series_plan_jobs.get(job_id)
        if cached:
            return copy.deepcopy(cached)
    for item in _list_workspaces():
        try:
            job = _series_plan_store(item["name"]).load(job_id)
        except (OSError, ValueError, json.JSONDecodeError):
            continue
        if job:
            with _series_plan_jobs_lock:
                _series_plan_jobs[job_id] = job
            return copy.deepcopy(job)
    return None


def _series_plan_update(job_id: str, **patch) -> dict | None:
    with _series_plan_jobs_lock:
        job = _series_plan_jobs.get(job_id)
        if not job:
            return None
        if (
            job.get("status") == "cancelling"
            and patch.get("status") not in {"cancelling", "cancelled"}
        ):
            return copy.deepcopy(job)
        job.update(copy.deepcopy(patch))
        job["updatedAt"] = time.time()
        snapshot = copy.deepcopy(job)
        _series_plan_store(str(job["workspace"])).save(snapshot)
        publisher = globals().get("_publish_series_task")
        if callable(publisher):
            try:
                publisher(snapshot, "series-plan")
            except Exception as exc:
                print(f"[Task registry] Could not publish Series plan {job_id}: {exc}")
        return snapshot


def _series_plan_request(body: dict, series: dict, episode: dict) -> dict:
    """Freeze planning inputs while excluding media and render history."""
    from services.series_library import series_for_episode_snapshot

    series_snapshot = series_for_episode_snapshot(series, episode)
    series_snapshot.pop("assets", None)
    prior_episode_summaries = []
    current_number = int(episode.get("number") or 0)
    for previous in sorted(
        (
            item for item in series.get("episodesById", {}).values()
            if isinstance(item, dict)
            and item.get("id") != episode.get("id")
            and int(item.get("number") or 0) < current_number
        ),
        key=lambda item: int(item.get("number") or 0),
    )[-12:]:
        outline = previous.get("outline") if isinstance(previous.get("outline"), dict) else {}
        prior_episode_summaries.append({
            "id": previous.get("id"),
            "number": previous.get("number"),
            "title": previous.get("title"),
            "logline": previous.get("logline"),
            "status": previous.get("status"),
            "outlineBeats": [
                str(value)[:500] for value in outline.get("beats", [])[:8]
                if isinstance(value, str) and value.strip()
            ],
        })
    series_snapshot["episodesById"] = {}
    series_snapshot["priorEpisodeSummaries"] = prior_episode_summaries
    episode_snapshot = copy.deepcopy(episode)
    for shot in episode_snapshot.get("shots", []):
        if isinstance(shot, dict):
            shot.pop("attempts", None)
            shot.pop("referenceManifest", None)
    return {
        "scope": str(body.get("scope") or "complete"),
        "instruction": str(body.get("instruction") or "")[:8000],
        "writingProvider": str(body.get("writingProvider") or series.get("provider", {}).get("writingProvider") or "maestro"),
        "writingModel": str(body.get("writingModel") or series.get("provider", {}).get("writingModel") or ""),
        "writingBaseUrl": str(body.get("writingBaseUrl") or series.get("provider", {}).get("writingBaseUrl") or ""),
        "seriesSnapshot": series_snapshot,
        "episodeSnapshot": episode_snapshot,
    }


def _run_series_plan_job_inner(job_id: str) -> None:
    from services.series_planning import (
        apply_planning_stage,
        normalize_planning_result,
        planning_output_token_budget,
        planning_prompt,
        planning_schema,
        planning_stages,
    )

    job = _load_series_plan_job(job_id)
    if not job:
        return
    if job.get("status") in {"cancelling", "cancelled"}:
        return
    request = copy.deepcopy(job.get("request") or {})
    series = request.get("seriesSnapshot") if isinstance(request.get("seriesSnapshot"), dict) else {}
    episode = request.get("episodeSnapshot") if isinstance(request.get("episodeSnapshot"), dict) else {}
    completed = job.get("completedStages") if isinstance(job.get("completedStages"), dict) else {}
    try:
        stages = planning_stages(str(request.get("scope") or "complete"))
        llm_override = _comic_writing_llm(request)
        if not llm_override:
            _ensure_llm_loaded()
        for index, stage in enumerate(stages):
            latest = _load_series_plan_job(job_id)
            if latest and latest.get("status") in {"cancelling", "cancelled"}:
                return
            if stage in completed:
                result = normalize_planning_result(stage, completed[stage], series, episode)
            else:
                _series_plan_update(
                    job_id, status="running", stage=stage, current=index, total=len(stages),
                    message=f"Generating Series Lab {stage.replace('_', ' ')}…",
                )
                prompt, system_prompt = planning_prompt(
                    stage, series, episode, str(request.get("instruction") or ""),
                )
                raw = _generate_comic_director_json(
                    prompt=prompt,
                    system_prompt=system_prompt,
                    schema=planning_schema(stage, episode),
                    # Long episodes need proportionally more independent
                    # 5/10/15-second clips; keep enough output room for their
                    # complete structured shot records.
                    max_new_tokens=planning_output_token_budget(stage, episode),
                    stage=f"Series Lab {stage}",
                    llm_override=llm_override,
                )
                # JSON-schema support differs between providers. A response can
                # be valid JSON yet still violate a cross-field production rule
                # such as "every speaker is visible" or the single-speaker clip
                # limit. Give the writing model two bounded, evidence-rich
                # semantic repair passes instead of throwing away all earlier
                # durable stages after the first invalid response.
                semantic_error = None
                for repair_attempt in range(3):
                    try:
                        result = normalize_planning_result(stage, raw, series, episode)
                        semantic_error = None
                        break
                    except ValueError as exc:
                        semantic_error = exc
                        if repair_attempt >= 2:
                            raise
                        previous_response = json.dumps(
                            raw, ensure_ascii=False, separators=(",", ":"), default=str,
                        )
                        previous_limit = min(
                            250000,
                            planning_output_token_budget(stage, episode) * 4,
                        )
                        if len(previous_response) > previous_limit:
                            previous_response = (
                                previous_response[:previous_limit]
                                + "\n[previous response truncated for bounded Series Lab repair]"
                            )
                        _series_plan_update(
                            job_id,
                            status="running",
                            stage=stage,
                            current=index,
                            total=len(stages),
                            validationAttempt=repair_attempt + 1,
                            validationError=str(exc),
                            message=(
                                f"Repairing Series Lab {stage.replace('_', ' ')} "
                                f"({repair_attempt + 1}/2): {exc}"
                            ),
                        )
                        repair_prompt = (
                            f"{prompt}\n\nSERIES STAGE VALIDATION REPAIR: The previous response "
                            f"failed this production rule: {exc}. Preserve all valid story facts and "
                            "dialogue, but correct the smallest necessary structure. For a shot with "
                            "more than one actual dialogue speaker, distribute every speaker turn across "
                            "separate single-speaker shots. Keep the duration-aware shot count stated above; "
                            "use only 5, 10, or 15 seconds and never exceed 15 seconds. "
                            "speakingCharacterIds must "
                            "equal the unique characterId values in dialogueBeats, not every visible "
                            "participant. Return exactly one complete JSON object matching the schema.\n"
                            f"PREVIOUS RESPONSE TO REPAIR:\n{previous_response}"
                        )
                        raw = _generate_comic_director_json(
                            prompt=repair_prompt,
                            system_prompt=system_prompt,
                            schema=planning_schema(stage, episode),
                            max_new_tokens=planning_output_token_budget(stage, episode),
                            stage=f"Series Lab {stage} validation repair {repair_attempt + 1}",
                            llm_override=llm_override,
                        )
                        latest = _load_series_plan_job(job_id)
                        if latest and latest.get("status") in {"cancelling", "cancelled"}:
                            return
                if semantic_error is not None:  # pragma: no cover - loop raises first
                    raise semantic_error
                latest = _load_series_plan_job(job_id)
                if latest and latest.get("status") in {"cancelling", "cancelled"}:
                    return
                completed[stage] = result
            episode = apply_planning_stage(episode, stage, result)
            _series_plan_update(
                job_id, completedStages=completed, episodeResult=episode,
                current=index + 1, stage=stage, validationAttempt=0, validationError=None,
            )
        _series_plan_update(
            job_id, status="completed", stage="completed", current=len(stages), total=len(stages),
            message="Episode proposal generated. Review and apply it when ready.",
            result={"episode": episode}, error=None, finishedAt=time.time(),
        )
    except Exception as exc:
        latest = _load_series_plan_job(job_id)
        if latest and latest.get("status") in {"cancelling", "cancelled"}:
            outcome = _llm_abort_outcome(exc)
            if latest.get("status") == "cancelling" and outcome is not None:
                _series_plan_update(
                    job_id,
                    status="cancelling",
                    cancellationAbortSupported=outcome,
                    message=_planning_cancel_message("Series planning", outcome),
                )
            return
        detail = exc.detail if isinstance(exc, HTTPException) else str(exc)
        _series_plan_update(
            job_id, status="failed", error=str(detail), finishedAt=time.time(),
            message="Episode planning stopped. Completed stages remain recoverable.",
        )


def _apply_series_canon_proposal(job: dict, proposal: dict) -> dict:
    """Apply a durable canon proposal while preserving user-owned assets and runtime state."""
    from services.series_planning import merge_series_canon_proposal

    workspace = str(job["workspace"])
    series_id = str(job["seriesId"])
    bootstrap_known_series = job.get("bootstrapKnownSeries") is True
    with _series_library_lock:
        library = _read_series_workspace(workspace)
        series = copy.deepcopy(_series_project_or_404(library, series_id))
        if int(series.get("revision") or 1) != int(job.get("sourceSeriesRevision") or 1):
            raise HTTPException(
                status_code=409,
                detail="The series was edited after canon preparation started. Review the saved proposal instead of overwriting it.",
            )
        series = merge_series_canon_proposal(
            series, proposal, bootstrap_known_series=bootstrap_known_series,
        )
        now = datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")
        series["revision"] = int(series.get("revision") or 1) + 1
        series["updatedAt"] = now
        library["seriesById"][series_id] = series
        stored = _write_series_workspace(workspace, library)
    return stored["seriesById"][series_id]


def _run_series_canon_plan_job_inner(job_id: str) -> None:
    from services.series_planning import (
        canon_preparation_prompt,
        canon_preparation_schema,
        known_series_bootstrap_prompt,
        known_series_bootstrap_schema,
        normalize_canon_preparation,
        normalize_known_series_bootstrap,
    )

    job = _load_series_plan_job(job_id)
    if not job:
        return
    if job.get("status") in {"cancelling", "cancelled"}:
        return
    request = copy.deepcopy(job.get("request") or {})
    series = request.get("seriesSnapshot") if isinstance(request.get("seriesSnapshot"), dict) else {}
    try:
        llm_override = _comic_writing_llm(request)
        if not llm_override:
            _ensure_llm_loaded()
        bootstrap_known_series = job.get("bootstrapKnownSeries") is True
        _series_plan_update(
            job_id, status="running", stage="known_series_research" if bootstrap_known_series else "canon",
            current=0, total=1,
            message=(
                "Building an editable known-series bible from the writing model's general knowledge…"
                if bootstrap_known_series else "Preparing a reviewable Series canon proposal…"
            ),
        )
        if bootstrap_known_series:
            prompt, system_prompt = known_series_bootstrap_prompt(
                series, str(request.get("instruction") or ""),
            )
            schema = known_series_bootstrap_schema()
            max_new_tokens = 14000
            stage_label = "Series Lab known-series bootstrap"
        else:
            prompt, system_prompt = canon_preparation_prompt(
                series, str(request.get("instruction") or ""),
            )
            schema = canon_preparation_schema()
            max_new_tokens = 6000
            stage_label = "Series Lab canon preparation"
        raw = _generate_comic_director_json(
            prompt=prompt, system_prompt=system_prompt,
            schema=schema, max_new_tokens=max_new_tokens,
            stage=stage_label, llm_override=llm_override,
        )
        latest = _load_series_plan_job(job_id)
        if latest and latest.get("status") in {"cancelling", "cancelled"}:
            return
        proposal = (
            normalize_known_series_bootstrap(raw, series)
            if bootstrap_known_series else normalize_canon_preparation(raw, series)
        )
        if bootstrap_known_series and job.get("autoApply") is True:
            _series_plan_update(
                job_id, stage="applying_draft", seriesResult=proposal,
                result={"seriesProposal": proposal},
                message="Known-series bible generated; applying it as an editable draft…",
            )
            latest = _load_series_plan_job(job_id)
            if latest and latest.get("status") in {"cancelling", "cancelled"}:
                return
            try:
                applied = _apply_series_canon_proposal(job, proposal)
            except HTTPException as exc:
                _series_plan_update(
                    job_id, status="completed", stage="completed", current=1, total=1,
                    autoApplied=False, applyError=str(exc.detail), error=None,
                    message="Known-series proposal generated, but the project changed before it could be applied.",
                    finishedAt=time.time(),
                )
                return
            _series_plan_update(
                job_id, status="completed", stage="completed", current=1, total=1,
                autoApplied=True, appliedSeriesRevision=int(applied.get("revision") or 1),
                appliedAt=time.time(), error=None,
                message="Known-series bible filled as a draft. Verify facts and approve canon when ready.",
                finishedAt=time.time(),
            )
            return
        _series_plan_update(
            job_id, status="completed", stage="completed", current=1, total=1,
            seriesResult=proposal, result={"seriesProposal": proposal}, error=None,
            message="Canon proposal generated. Review it before applying.",
            finishedAt=time.time(),
        )
    except Exception as exc:
        latest = _load_series_plan_job(job_id)
        if latest and latest.get("status") in {"cancelling", "cancelled"}:
            outcome = _llm_abort_outcome(exc)
            if latest.get("status") == "cancelling" and outcome is not None:
                _series_plan_update(
                    job_id,
                    status="cancelling",
                    cancellationAbortSupported=outcome,
                    message=_planning_cancel_message("Canon preparation", outcome),
                )
            return
        detail = exc.detail if isinstance(exc, HTTPException) else str(exc)
        _series_plan_update(
            job_id, status="failed", error=str(detail), finishedAt=time.time(),
            message="Canon preparation stopped. Its checkpoint remains recoverable.",
        )


def _run_series_plan_job(job_id: str) -> None:
    with _series_plan_jobs_lock:
        if job_id in _series_plan_active_jobs:
            return
        _series_plan_active_jobs.add(job_id)
    try:
        job = _load_series_plan_job(job_id)
        task = _publish_series_task(job, "series-plan") if job else None
        if task:
            from services.task_manager import task_context_scope
            scope = task_context_scope(
                task_id=task["id"], root_id=task["root_id"],
                workspace=str(job.get("workspace") or "default"),
                workspace_dir=_workspace_dir(str(job.get("workspace") or "default")),
            )
        else:
            from contextlib import nullcontext
            scope = nullcontext()
        with scope:
            if job and job.get("jobType") == "canon":
                _run_series_canon_plan_job_inner(job_id)
            else:
                _run_series_plan_job_inner(job_id)
    finally:
        with _series_plan_jobs_lock:
            _series_plan_active_jobs.discard(job_id)
        settling = _load_series_plan_job(job_id) or {}
        if settling.get("status") == "cancelling":
            _series_plan_update(
                job_id,
                status="cancelled",
                stage="cancelled",
                finishedAt=time.time(),
                message=_planning_cancel_message(
                    "Series planning",
                    settling.get("cancellationAbortSupported")
                    if isinstance(settling.get("cancellationAbortSupported"), bool)
                    else None,
                ),
            )


@api.post("/api/v1/series/{series_id}/canon/prepare/start")
def start_series_canon_preparation(series_id: str, body: dict):
    workspace = _series_library_workspace(body.get("workspace"))
    with _series_library_lock:
        library = _read_series_workspace(workspace)
        series = copy.deepcopy(_series_project_or_404(library, series_id))
    bootstrap_known_series = body.get("bootstrapKnownSeries") is True
    instruction = str(body.get("instruction") or "")[:8000].strip()
    if bootstrap_known_series and len(instruction) < 3:
        raise HTTPException(status_code=400, detail="Describe the known series you want to continue")
    missing = [
        label for label, value in (
            ("title", series.get("title")), ("premise", series.get("premise")),
            ("visual style", series.get("visualStyle")),
        ) if not str(value or "").strip()
    ]
    if missing and not bootstrap_known_series:
        raise HTTPException(
            status_code=400,
            detail=f"Complete Series setup before preparing canon: {', '.join(missing)}",
        )
    snapshot = copy.deepcopy(series)
    snapshot.pop("assets", None)
    snapshot["episodesById"] = {}
    request = {
        "instruction": instruction,
        "writingProvider": str(body.get("writingProvider") or series.get("provider", {}).get("writingProvider") or "maestro"),
        "writingModel": str(body.get("writingModel") or series.get("provider", {}).get("writingModel") or ""),
        "writingBaseUrl": str(body.get("writingBaseUrl") or series.get("provider", {}).get("writingBaseUrl") or ""),
        "seriesSnapshot": snapshot,
        "bootstrapKnownSeries": bootstrap_known_series,
        "autoApply": bootstrap_known_series and body.get("autoApply") is not False,
    }
    _comic_writing_llm(request)
    job_id = f"series-canon-{uuid.uuid4().hex[:12]}"
    task_id = f"task-series-plan-{job_id}"
    now = time.time()
    job = {
        "jobId": job_id, "jobType": "canon", "kind": "planning",
        "workspace": workspace, "seriesId": series_id, "episodeId": "",
        "status": "queued", "stage": "queued", "current": 0, "total": 1,
        "message": "Canon preparation queued.", "request": request,
        "sourceSeriesRevision": int(series.get("revision") or 1),
        "seriesResult": None, "result": None, "error": None,
        "generateImages": body.get("generateImages") is True,
        "bootstrapKnownSeries": bootstrap_known_series,
        "autoApply": request["autoApply"], "autoApplied": False,
        "createdAt": now, "updatedAt": now,
        "taskId": task_id, "rootTaskId": task_id,
    }
    # Revalidate and publish the durable checkpoint while deletion holds the
    # same library lock. Either deletion wins and this start returns 404, or
    # the checkpoint wins and the deletion guard observes it.
    with _series_library_lock:
        _series_project_or_404(_read_series_workspace(workspace), series_id)
        with _series_plan_jobs_lock:
            _series_plan_jobs[job_id] = job
            _series_plan_store(workspace).save(job)
    publisher = globals().get("_publish_series_task")
    task = publisher(job, "series-plan") if callable(publisher) else None
    if isinstance(task, dict):
        job["taskId"] = task.get("id")
        job["rootTaskId"] = task.get("root_id") or task.get("id")
        with _series_plan_jobs_lock:
            _series_plan_jobs[job_id] = copy.deepcopy(job)
            _series_plan_store(workspace).save(job)
    threading.Thread(target=_run_series_plan_job, args=(job_id,), daemon=True).start()
    return {key: job[key] for key in (
        "jobId", "jobType", "workspace", "seriesId", "episodeId",
        "status", "stage", "current", "total", "message", "generateImages",
        "bootstrapKnownSeries", "autoApply", "autoApplied", "taskId",
        "rootTaskId", "createdAt",
    )}


@api.post("/api/v1/series/{series_id}/episodes/{episode_id}/plan/start")
def start_series_episode_plan(series_id: str, episode_id: str, body: dict):
    from services.series_planning import planning_stages

    workspace = _series_library_workspace(body.get("workspace"))
    scope = str(body.get("scope") or "complete")
    try:
        stages = planning_stages(scope)
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    with _series_library_lock:
        library = _read_series_workspace(workspace)
        series = _series_project_or_404(library, series_id)
        episode = series.get("episodesById", {}).get(episode_id)
        if not isinstance(episode, dict):
            raise HTTPException(status_code=404, detail="Series episode not found")
        if not str(episode.get("premise") or body.get("instruction") or "").strip():
            raise HTTPException(status_code=400, detail="Write an episode premise or instruction first")
        request = _series_plan_request(body, series, episode)
    # Resolve provider credentials before creating a durable job so a missing
    # key does not leave a permanently queued phantom checkpoint.
    _comic_writing_llm(request)
    job_id = f"series-plan-{uuid.uuid4().hex[:12]}"
    task_id = f"task-series-plan-{job_id}"
    now = time.time()
    job = {
        "jobId": job_id, "kind": "planning", "workspace": workspace,
        "seriesId": series_id, "episodeId": episode_id,
        "status": "queued", "stage": "queued", "current": 0, "total": len(stages),
        "message": "Episode planning queued.", "request": request,
        "sourceSeriesRevision": int(series.get("revision") or 1),
        "sourceEpisodeUpdatedAt": episode.get("updatedAt"),
        "completedStages": {}, "episodeResult": None, "result": None, "error": None,
        "createdAt": now, "updatedAt": now,
        "taskId": task_id, "rootTaskId": task_id,
    }
    # Revalidate and publish atomically with respect to Series deletion.
    with _series_library_lock:
        current_series = _series_project_or_404(_read_series_workspace(workspace), series_id)
        if not isinstance(current_series.get("episodesById", {}).get(episode_id), dict):
            raise HTTPException(status_code=404, detail="Series episode not found")
        with _series_plan_jobs_lock:
            _series_plan_jobs[job_id] = job
            _series_plan_store(workspace).save(job)
    publisher = globals().get("_publish_series_task")
    task = publisher(job, "series-plan") if callable(publisher) else None
    if isinstance(task, dict):
        job["taskId"] = task.get("id")
        job["rootTaskId"] = task.get("root_id") or task.get("id")
        with _series_plan_jobs_lock:
            _series_plan_jobs[job_id] = copy.deepcopy(job)
            _series_plan_store(workspace).save(job)
    threading.Thread(target=_run_series_plan_job, args=(job_id,), daemon=True).start()
    return {key: job[key] for key in (
        "jobId", "taskId", "rootTaskId", "workspace", "seriesId", "episodeId",
        "status", "stage", "current",
        "total", "message", "createdAt",
    )}


@api.get("/api/v1/series/plan/jobs/{job_id}")
def get_series_episode_plan(job_id: str):
    job = _load_series_plan_job(job_id)
    if not job:
        raise HTTPException(status_code=404, detail="Series planning job not found")
    return {key: job.get(key) for key in (
        "jobId", "jobType", "workspace", "seriesId", "episodeId", "status", "stage", "current", "total",
        "message", "completedStages", "episodeResult", "seriesResult", "generateImages",
        "validationAttempt", "validationError",
        "bootstrapKnownSeries", "autoApply", "autoApplied", "appliedSeriesRevision", "applyError",
        "result", "error", "createdAt", "updatedAt", "finishedAt", "appliedAt",
        "taskId", "rootTaskId",
    )}


@api.post("/api/v1/series/plan/jobs/{job_id}/cancel")
def cancel_series_episode_plan(job_id: str):
    job = _load_series_plan_job(job_id)
    if not job:
        raise HTTPException(status_code=404, detail="Series planning job not found")
    if job.get("status") in {"completed", "failed", "cancelled"}:
        return {"jobId": job_id, "status": job.get("status"), "message": job.get("message")}
    with _series_plan_jobs_lock:
        worker_active = job_id in _series_plan_active_jobs
    updated = _series_plan_update(
        job_id,
        status="cancelling" if worker_active else "cancelled",
        stage="cancelling" if worker_active else "cancelled",
        finishedAt=None if worker_active else time.time(),
        message=(
            "Series planning cancellation requested; aborting the active LLM "
            "response where supported, otherwise waiting for its safe boundary."
            if worker_active else
            "Series planning cancelled before an LLM call started."
        ),
    )
    return {
        "jobId": job_id,
        "status": updated.get("status"),
        "message": updated.get("message"),
    }


@api.post("/api/v1/series/plan/jobs/{job_id}/resume")
def resume_series_episode_plan(job_id: str, body: dict | None = None):
    job = _load_series_plan_job(job_id)
    if not job:
        raise HTTPException(status_code=404, detail="Series planning job not found")
    if job.get("status") == "completed":
        return {"jobId": job_id, "status": "completed", "message": job.get("message")}
    with _series_plan_jobs_lock:
        if job_id in _series_plan_active_jobs:
            return {"jobId": job_id, "status": job.get("status"), "message": "Planning is already running."}
    request = copy.deepcopy(job.get("request") or {})
    if isinstance(body, dict) and str(body.get("writingProvider") or "").strip():
        for key in ("writingProvider", "writingModel", "writingBaseUrl"):
            if key in body:
                request[key] = body[key]
        _comic_writing_llm(request)
    workspace = str(job.get("workspace") or "default")
    with _series_library_lock:
        current_series = _series_project_or_404(
            _read_series_workspace(workspace), str(job.get("seriesId") or ""),
        )
        episode_id = str(job.get("episodeId") or "")
        if episode_id and not isinstance(current_series.get("episodesById", {}).get(episode_id), dict):
            raise HTTPException(status_code=404, detail="Series episode not found")
        _reset_canonical_task_for_resume(
            workspace,
            str(job.get("taskId") or f"task-series-plan-{job_id}"),
        )
        _series_plan_update(
            job_id, request=request, status="queued", error=None, finishedAt=None,
            message="Resuming episode planning from the last completed stage…",
        )
    threading.Thread(target=_run_series_plan_job, args=(job_id,), daemon=True).start()
    return {"jobId": job_id, "status": "queued", "message": "Episode planning resumed."}


def _prepare_edited_series_episode_proposal(stored: dict, edited: dict | None, series: dict) -> dict:
    """Merge reviewable fields while keeping generated identities and protected state authoritative."""
    if edited is None:
        return copy.deepcopy(stored)
    if not isinstance(edited, dict):
        raise ValueError("Edited episode proposal must be an object")
    if edited.get("id") not in {None, "", stored.get("id")}:
        raise ValueError("Edited episode proposal id does not match the generated proposal")

    proposed = copy.deepcopy(stored)
    outline = edited.get("outline")
    beats = outline.get("beats") if isinstance(outline, dict) else None
    if not isinstance(beats, list) or any(not isinstance(beat, str) for beat in beats):
        raise ValueError("Edited outline beats must be text values")
    proposed["outline"] = {"beats": copy.deepcopy(beats)}

    def merge_identified(original_items, edited_items, label, editable_keys, *, ordered=False):
        if not isinstance(original_items, list) or not isinstance(edited_items, list):
            raise ValueError(f"Edited {label} must be a list")
        original_ids = [str(item.get("id") or "") for item in original_items if isinstance(item, dict)]
        edited_by_id = {
            str(item.get("id") or ""): item for item in edited_items if isinstance(item, dict)
        }
        if (
            len(original_ids) != len(original_items)
            or len(edited_by_id) != len(edited_items)
            or set(original_ids) != set(edited_by_id)
        ):
            raise ValueError(f"Edited {label} cannot add, remove, duplicate, or replace internal IDs")
        merged = []
        for index, original in enumerate(original_items):
            item = copy.deepcopy(original)
            revision = edited_by_id[str(original["id"])]
            for key in editable_keys:
                if key in revision:
                    item[key] = copy.deepcopy(revision[key])
            item["id"] = original["id"]
            if ordered:
                item["order"] = index + 1
            merged.append(item)
        return merged

    scene_keys = (
        "locationId", "locationVariantId", "time", "participatingCharacterIds", "purpose",
        "entryState", "exitState", "beats", "dialogue",
    )
    proposed["script"] = merge_identified(
        stored.get("script"), edited.get("script"), "script scenes", scene_keys, ordered=True,
    )
    for original_scene, scene in zip(stored.get("script", []), proposed["script"]):
        scene["beats"] = merge_identified(
            original_scene.get("beats"), scene.get("beats"), "scene beats", ("kind", "summary"),
        )
        scene["dialogue"] = merge_identified(
            original_scene.get("dialogue"), scene.get("dialogue"), "scene dialogue", ("characterId", "text", "emotion", "delivery"),
        )

    shot_keys = (
        "sceneId", "durationSeconds", "framing", "camera", "action", "dialogueBeats",
        "visibleCharacterIds", "locationId", "locationVariantId", "wardrobeByCharacterId",
        "propIds", "emotionalStateByCharacterId", "continuityFromShotId", "renderStrategy",
        "referencePolicy", "prompt", "negativePrompt", "audioDirection",
    )
    proposed["shots"] = merge_identified(
        stored.get("shots"), edited.get("shots"), "shots", shot_keys, ordered=True,
    )
    for original_shot, shot in zip(stored.get("shots", []), proposed["shots"]):
        shot["dialogueBeats"] = merge_identified(
            original_shot.get("dialogueBeats"), shot.get("dialogueBeats"), "shot dialogue", ("characterId", "text", "emotion", "delivery"),
        )

    character_ids = {str(item.get("id")) for item in series.get("characters", []) if isinstance(item, dict)}
    location_ids = {str(item.get("id")) for item in series.get("locations", []) if isinstance(item, dict)}
    scene_ids = {str(item["id"]) for item in proposed["script"]}
    shot_ids = {str(item["id"]) for item in proposed["shots"]}
    for scene in proposed["script"]:
        if scene.get("locationId") not in location_ids:
            raise ValueError(f"Scene {scene['id']} uses an unknown location")
        dialogue_speakers = []
        for line in scene["dialogue"]:
            character_id = str(line.get("characterId") or "")
            if character_id not in character_ids:
                raise ValueError(f"Scene {scene['id']} dialogue uses an unknown character")
            if character_id not in dialogue_speakers:
                dialogue_speakers.append(character_id)
        scene["participatingCharacterIds"] = list(dict.fromkeys([
            *[str(item) for item in scene.get("participatingCharacterIds", []) if str(item) in character_ids],
            *dialogue_speakers,
        ]))
    for shot in proposed["shots"]:
        if shot.get("sceneId") not in scene_ids:
            raise ValueError(f"Shot {shot['id']} uses an unknown scene")
        if shot.get("locationId") and shot.get("locationId") not in location_ids:
            raise ValueError(f"Shot {shot['id']} uses an unknown location")
        try:
            duration_value = float(shot.get("durationSeconds"))
            if not math.isfinite(duration_value) or duration_value <= 0:
                raise ValueError
        except (TypeError, ValueError):
            raise ValueError(f"Shot {shot['id']} duration must be a positive number")
        continuity_id = str(shot.get("continuityFromShotId") or "")
        if continuity_id and continuity_id not in shot_ids:
            raise ValueError(f"Shot {shot['id']} references an unknown continuity shot")
        visible = list(dict.fromkeys(
            str(item) for item in shot.get("visibleCharacterIds", []) if str(item) in character_ids
        ))
        dialogue_speakers = []
        for line in shot["dialogueBeats"]:
            character_id = str(line.get("characterId") or "")
            if character_id not in character_ids:
                raise ValueError(f"Shot {shot['id']} dialogue uses an unknown character")
            if character_id not in visible:
                visible.append(character_id)
            if character_id not in dialogue_speakers:
                dialogue_speakers.append(character_id)
        if len(dialogue_speakers) > 1:
            raise ValueError(f"Shot {shot['id']} must contain dialogue from only one speaker")
        shot["visibleCharacterIds"] = visible
        shot["speakingCharacterIds"] = dialogue_speakers
        shot["primarySpeakerId"] = dialogue_speakers[0] if dialogue_speakers else ""

    from services.series_render import apply_series_shot_duration
    for shot in proposed["shots"]:
        apply_series_shot_duration(series, shot)

    edited_delta = edited.get("proposedCanonDelta")
    stored_delta = stored.get("proposedCanonDelta")
    if not isinstance(edited_delta, dict) or not isinstance(stored_delta, dict):
        raise ValueError("Edited canon delta must be an object")
    delta = copy.deepcopy(stored_delta)
    for key in ("add", "change"):
        delta[key] = merge_identified(
            stored_delta.get(key), edited_delta.get(key), f"canon {key}", ("description", "decision"),
        )
    # Retire entries use factId rather than id; only their decision is reviewable.
    stored_retire = stored_delta.get("retire") if isinstance(stored_delta.get("retire"), list) else []
    edited_retire = edited_delta.get("retire") if isinstance(edited_delta.get("retire"), list) else []
    edited_retire_by_id = {str(item.get("factId") or ""): item for item in edited_retire if isinstance(item, dict)}
    if len(edited_retire_by_id) != len(stored_retire) or {
        str(item.get("factId") or "") for item in stored_retire
    } != set(edited_retire_by_id):
        raise ValueError("Edited canon retire list cannot change internal fact IDs")
    delta["retire"] = [
        {**copy.deepcopy(item), "decision": edited_retire_by_id[str(item.get("factId") or "")].get("decision", item.get("decision"))}
        for item in stored_retire
    ]
    proposed["proposedCanonDelta"] = delta
    proposed["continuityIssues"] = copy.deepcopy(stored.get("continuityIssues"))
    return proposed


@api.post("/api/v1/series/{series_id}/shots/duration/preview")
def preview_series_shot_duration(series_id: str, body: dict):
    """Preview the same authoritative duration contract used by save/render."""
    from services.series_render import plan_series_shot_duration

    workspace = _series_library_workspace(body.get("workspace"))
    shot = body.get("shot")
    if not isinstance(shot, dict):
        raise HTTPException(status_code=400, detail="Series shot is required")
    with _series_library_lock:
        series = copy.deepcopy(_series_project_or_404(
            _read_series_workspace(workspace), series_id,
        ))
    try:
        return plan_series_shot_duration(series, shot)
    except (TypeError, ValueError) as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc


@api.post("/api/v1/series/plan/jobs/{job_id}/apply")
def apply_series_episode_plan(job_id: str, body: dict | None = None):
    job = _load_series_plan_job(job_id)
    if not job:
        raise HTTPException(status_code=404, detail="Series planning job not found")
    if job.get("jobType") == "canon":
        raise HTTPException(status_code=400, detail="Use the canon proposal apply endpoint for this job")
    if job.get("status") != "completed" or not isinstance(job.get("episodeResult"), dict):
        raise HTTPException(status_code=400, detail="Complete the planning job before applying it")
    workspace = str(job["workspace"])
    series_id = str(job["seriesId"])
    episode_id = str(job["episodeId"])
    with _series_library_lock:
        library = _read_series_workspace(workspace)
        series = copy.deepcopy(_series_project_or_404(library, series_id))
        current = series.get("episodesById", {}).get(episode_id)
        if not isinstance(current, dict):
            raise HTTPException(status_code=404, detail="Series episode not found")
        if current.get("updatedAt") != job.get("sourceEpisodeUpdatedAt"):
            raise HTTPException(
                status_code=409,
                detail="The episode was edited after planning started. Review the saved proposal instead of overwriting it.",
            )
        try:
            proposed = _prepare_edited_series_episode_proposal(
                job["episodeResult"], body.get("episodeResult") if isinstance(body, dict) else None, series,
            )
        except ValueError as exc:
            raise HTTPException(status_code=400, detail=str(exc)) from exc
        proposed["canonSnapshot"] = copy.deepcopy(current.get("canonSnapshot"))
        proposed["canonRevisionAtCreation"] = current.get("canonRevisionAtCreation")
        proposed["createdAt"] = current.get("createdAt")
        proposed["updatedAt"] = datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")
        # Route exact manifests now so review shows what generation will send.
        from services.series_library import series_for_episode_snapshot
        from services.series_reference_router import route_shot_references
        routing_series = series_for_episode_snapshot(series, proposed)
        for shot in proposed.get("shots", []):
            if isinstance(shot, dict):
                shot["referenceManifest"] = route_shot_references(routing_series, proposed, shot)
        series["episodesById"][episode_id] = proposed
        series["revision"] = int(series.get("revision") or 1) + 1
        series["updatedAt"] = proposed["updatedAt"]
        library["seriesById"][series_id] = series
        stored = _write_series_workspace(workspace, library)
    _series_plan_update(job_id, appliedAt=time.time(), message="Episode proposal applied for review.")
    return stored["seriesById"][series_id]["episodesById"][episode_id]


@api.post("/api/v1/series/plan/jobs/{job_id}/apply-canon")
def apply_series_canon_plan(job_id: str):
    job = _load_series_plan_job(job_id)
    if not job:
        raise HTTPException(status_code=404, detail="Series canon planning job not found")
    proposal = job.get("seriesResult")
    if job.get("jobType") != "canon" or job.get("status") != "completed" or not isinstance(proposal, dict):
        raise HTTPException(status_code=400, detail="Complete the canon preparation job before applying it")
    applied = _apply_series_canon_proposal(job, proposal)
    _series_plan_update(job_id, appliedAt=time.time(), message="Canon proposal applied as a draft for review.")
    return applied


@api.get("/api/v1/series/plan/recovery")
def list_series_plan_recovery(workspace: str | None = None):
    target_workspace = _series_library_workspace(workspace)
    jobs = _series_plan_store(target_workspace).recoverable()
    return {"jobs": [{key: job.get(key) for key in (
        "jobId", "jobType", "seriesId", "episodeId", "status", "stage", "current", "total", "generateImages",
        "bootstrapKnownSeries", "autoApply", "autoApplied",
        "message", "error", "createdAt", "updatedAt",
    )} for job in jobs]}


@api.delete("/api/v1/series/plan/jobs/{job_id}")
def discard_series_plan_job(job_id: str):
    job = _load_series_plan_job(job_id)
    if not job:
        raise HTTPException(status_code=404, detail="Series planning job not found")
    with _series_plan_jobs_lock:
        if job_id in _series_plan_active_jobs:
            raise HTTPException(status_code=409, detail="Cancel the active planning job before discarding it")
        _series_plan_store(str(job["workspace"])).discard(job_id)
        _series_plan_jobs.pop(job_id, None)
    return {"discarded": True, "jobId": job_id, "outputsPreserved": True}


_series_render_jobs: dict[str, dict] = {}
_series_render_jobs_lock = threading.RLock()
_series_render_active_jobs: set[str] = set()


def _series_iso_now() -> str:
    return datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")


def _series_render_store(workspace: str):
    from services.series_jobs import SeriesJobStore

    return SeriesJobStore(_workspace_dir(workspace), "render")


def _active_series_render_for_episode(
    workspace: str, series_id: str, episode_id: str,
) -> dict | None:
    """Return the one queue that owns an episode, including after restart."""
    active_statuses = {"queued", "running", "cancelling"}
    with _series_render_jobs_lock:
        cached = [copy.deepcopy(job) for job in _series_render_jobs.values()]
    try:
        persisted = _series_render_store(workspace).list()
    except (OSError, ValueError, json.JSONDecodeError):
        persisted = []
    by_id = {
        str(job.get("jobId")): job
        for job in [*persisted, *cached]
        if isinstance(job, dict) and job.get("jobId")
    }
    return next((
        job for job in by_id.values()
        if job.get("workspace") == workspace
        and job.get("seriesId") == series_id
        and job.get("episodeId") == episode_id
        and job.get("status") in active_statuses
    ), None)


def _load_series_render_job(job_id: str) -> dict | None:
    with _series_render_jobs_lock:
        cached = _series_render_jobs.get(job_id)
        if cached:
            return copy.deepcopy(cached)
    for item in _list_workspaces():
        try:
            job = _series_render_store(item["name"]).load(job_id)
        except (OSError, ValueError, json.JSONDecodeError):
            continue
        if job:
            with _series_render_jobs_lock:
                _series_render_jobs[job_id] = job
            return copy.deepcopy(job)
    return None


def _series_render_update(job_id: str, **patch) -> dict | None:
    with _series_render_jobs_lock:
        job = _series_render_jobs.get(job_id)
        if not job:
            return None
        if (
            job.get("status") == "cancelling"
            and patch.get("status") not in {"cancelling", "cancelled"}
        ):
            return copy.deepcopy(job)
        job.update(copy.deepcopy(patch))
        job["updatedAt"] = time.time()
        snapshot = copy.deepcopy(job)
        _series_render_store(str(job["workspace"])).save(snapshot)
        publisher = globals().get("_publish_series_task")
        if callable(publisher):
            try:
                publisher(snapshot, "series-render")
            except Exception as exc:
                print(f"[Task registry] Could not publish Series render {job_id}: {exc}")
        return snapshot


def _series_render_update_item(job_id: str, item_index: int, **patch) -> dict | None:
    with _series_render_jobs_lock:
        job = _series_render_jobs.get(job_id)
        if not job:
            return None
        items = job.get("items") if isinstance(job.get("items"), list) else []
        if item_index < 0 or item_index >= len(items):
            return None
        items[item_index].update(copy.deepcopy(patch))
        job["items"] = items
        job["current"] = sum(1 for item in items if item.get("status") == "completed")
        job["updatedAt"] = time.time()
        snapshot = copy.deepcopy(job)
        _series_render_store(str(job["workspace"])).save(snapshot)
        return snapshot


def _series_asset_local_path(workspace: str, asset: dict) -> str:
    uri = str(asset.get("uri") or "")
    if uri.startswith("https://"):
        raise ValueError(
            f"Remote Series asset {asset.get('id')} must be imported into the workspace before local H3 rendering"
        )
    workspace_dir = os.path.realpath(_workspace_dir(workspace))
    relative = uri[len("outputs/"):] if uri.startswith("outputs/") else uri
    candidate = os.path.realpath(os.path.join(workspace_dir, relative))
    if candidate != workspace_dir and not candidate.startswith(workspace_dir + os.sep):
        raise ValueError(f"Series asset {asset.get('id')} leaves its workspace")
    if not os.path.isfile(candidate):
        raise ValueError(f"Series reference file is missing: {uri}")
    return candidate


def _series_render_context(job: dict, item: dict) -> tuple[dict, dict, dict, dict]:
    from services.series_library import series_for_episode_snapshot
    workspace = str(job["workspace"])
    with _series_library_lock:
        library = _read_series_workspace(workspace)
        series = _series_project_or_404(library, str(job["seriesId"]))
        episode = series.get("episodesById", {}).get(str(job["episodeId"]))
        if not isinstance(episode, dict):
            raise ValueError("Series episode no longer exists")
        shot = next((
            value for value in episode.get("shots", [])
            if isinstance(value, dict) and value.get("id") == item.get("shotId")
        ), None)
        if not isinstance(shot, dict):
            raise ValueError("Series shot no longer exists")
        attempt = next((
            value for value in shot.get("attempts", [])
            if isinstance(value, dict) and value.get("id") == item.get("attemptId")
        ), None)
        if not isinstance(attempt, dict):
            raise ValueError("Series render attempt no longer exists")
        frozen_series = series_for_episode_snapshot(series, episode)
        return frozen_series, copy.deepcopy(episode), copy.deepcopy(shot), copy.deepcopy(attempt)


def _series_patch_attempt(
    job: dict,
    item: dict,
    patch: dict,
    *,
    output_assets: list[dict] | None = None,
) -> dict:
    from services.series_library import update_shot_render_attempt

    workspace = str(job["workspace"])
    with _series_library_lock:
        library = _read_series_workspace(workspace)
        series = copy.deepcopy(_series_project_or_404(library, str(job["seriesId"])))
        episode = series.get("episodesById", {}).get(str(job["episodeId"]))
        if not isinstance(episode, dict):
            raise ValueError("Series episode no longer exists")
        shot_index = next((
            index for index, value in enumerate(episode.get("shots", []))
            if isinstance(value, dict) and value.get("id") == item.get("shotId")
        ), None)
        if shot_index is None:
            raise ValueError("Series shot no longer exists")
        episode["shots"][shot_index] = update_shot_render_attempt(
            episode["shots"][shot_index], str(item["attemptId"]), **patch,
        )
        for asset in output_assets or []:
            series.setdefault("assets", {})[asset["id"]] = copy.deepcopy(asset)
        now = _series_iso_now()
        episode["updatedAt"] = now
        series["updatedAt"] = now
        series["revision"] = int(series.get("revision") or 1) + 1
        library["seriesById"][series["id"]] = series
        stored = _write_series_workspace(workspace, library)
        return stored["seriesById"][series["id"]]["episodesById"][episode["id"]]["shots"][shot_index]


def _series_settle_episode_render_status(job: dict) -> str:
    """Leave an episode in a truthful terminal state after a render job settles."""
    workspace = str(job["workspace"])
    with _series_library_lock:
        library = _read_series_workspace(workspace)
        series = copy.deepcopy(_series_project_or_404(library, str(job["seriesId"])))
        episode = series.get("episodesById", {}).get(str(job["episodeId"]))
        if not isinstance(episode, dict):
            raise ValueError("Series episode no longer exists")
        shots = [item for item in episode.get("shots", []) if isinstance(item, dict)]
        all_rendered = bool(shots) and all(
            any(
                isinstance(attempt, dict)
                and attempt.get("status") == "completed"
                and bool(attempt.get("outputAssetIds"))
                for attempt in shot.get("attempts", [])
            )
            for shot in shots
        )
        status = "completed" if all_rendered else "shot_plan"
        if episode.get("status") == status:
            return status
        now = _series_iso_now()
        episode["status"] = status
        episode["updatedAt"] = now
        series["updatedAt"] = now
        series["revision"] = int(series.get("revision") or 1) + 1
        library["seriesById"][series["id"]] = series
        _write_series_workspace(workspace, library)
        return status


def _run_series_render_job_inner(job_id: str) -> None:
    from services.series_render import build_h3_generation_params

    job = _load_series_render_job(job_id)
    if not job:
        return
    items = job.get("items") if isinstance(job.get("items"), list) else []
    any_failed = False
    try:
        for item_index, item in enumerate(items):
            latest = _load_series_render_job(job_id)
            if not latest or latest.get("status") in {"cancelling", "cancelled"}:
                return
            current_item = latest.get("items", [])[item_index]
            if current_item.get("status") == "completed":
                continue
            series, _episode, shot, attempt = _series_render_context(latest, current_item)
            submitted_at = _series_iso_now()
            _series_patch_attempt(
                latest, current_item,
                {"status": "running", "submittedAt": submitted_at, "error": ""},
            )
            _series_render_update_item(
                job_id, item_index, status="running", submittedAt=submitted_at, error=None,
            )
            _series_render_update(
                job_id, status="running", stage="rendering", activeShotId=current_item["shotId"],
                message=f"Rendering shot {item_index + 1}/{len(items)}…",
            )
            latest = _load_series_render_job(job_id) or latest
            if latest.get("status") in {"cancelling", "cancelled"}:
                completed_at = _series_iso_now()
                _series_patch_attempt(
                    latest,
                    current_item,
                    {
                        "status": "cancelled",
                        "completedAt": completed_at,
                        "error": "Cancelled by user",
                    },
                )
                _series_render_update_item(
                    job_id,
                    item_index,
                    status="cancelled",
                    completedAt=completed_at,
                    error="Cancelled by user",
                )
                return
            started = time.time()
            child_job_id = ""
            try:
                assets = series.get("assets") if isinstance(series.get("assets"), dict) else {}
                resolved = {}
                for reference in attempt.get("referenceManifest", {}).get("selected", []):
                    if not isinstance(reference, dict):
                        continue
                    asset_id = str(reference.get("assetId") or "")
                    asset = assets.get(asset_id)
                    if not isinstance(asset, dict):
                        raise ValueError(f"Routed Series asset no longer exists: {asset_id}")
                    resolved[asset_id] = _series_asset_local_path(str(latest["workspace"]), asset)
                params = build_h3_generation_params(series, shot, attempt, resolved)
                params["_director_pipeline_id"] = f"series:{job_id}"
                cancellation_check = _load_series_render_job(job_id) or latest
                if cancellation_check.get("status") in {"cancelling", "cancelled"}:
                    raise RuntimeError("Cancelled by user before model execution")
                request_hash = "sha256:" + hashlib.sha256(
                    json.dumps(params, ensure_ascii=False, sort_keys=True, default=str).encode("utf-8")
                ).hexdigest()
                child_job_id = f"sr{uuid.uuid4().hex[:10]}"
                child = _new_generation_job(
                    params, str(latest["workspace"]), job_id=child_job_id,
                )
                _jobs[child_job_id] = child
                _series_render_update_item(
                    job_id, item_index, childJobId=child_job_id,
                    requestPayloadHash=request_hash,
                )
                cancellation_check = _load_series_render_job(job_id) or latest
                if cancellation_check.get("status") in {"cancelling", "cancelled"}:
                    _request_generation_cancel(child_job_id)
                    raise RuntimeError("Cancelled by user before model execution")
                _series_patch_attempt(
                    latest, current_item,
                    {"providerTaskId": child_job_id, "requestPayloadHash": request_hash},
                )
                _run_generation(child_job_id)
                child_result = snapshot_job(_jobs[child_job_id])
                if child_result.get("status") != "completed" or not child_result.get("output_files"):
                    raise RuntimeError(child_result.get("error") or "H3 returned no video output")
                completed_at = _series_iso_now()
                elapsed_ms = max(0, round((time.time() - started) * 1000))
                output_asset_ids = []
                output_assets = []
                for output_index, filename in enumerate(child_result["output_files"]):
                    basename = os.path.basename(str(filename))
                    asset_id = f"asset_{attempt['id']}_{output_index + 1}"
                    output_asset_ids.append(asset_id)
                    output_assets.append({
                        "id": asset_id, "workspaceId": latest["workspace"], "kind": "video",
                        "uri": f"outputs/{basename}", "ownerType": "attempt", "ownerId": attempt["id"],
                        "isDerivedThumbnail": False,
                        "metadata": {
                            "seriesId": latest["seriesId"], "episodeId": latest["episodeId"],
                            "shotId": current_item["shotId"], "attemptId": attempt["id"],
                            "prompt": attempt.get("prompt"), "negativePrompt": attempt.get("negativePrompt"),
                            "model": params["model_type"], "seed": params["seed"],
                            "settings": attempt.get("settings"),
                            "referenceManifest": attempt.get("referenceManifest"),
                            "createdAt": attempt.get("createdAt"), "submittedAt": submitted_at,
                            "completedAt": completed_at, "elapsedMs": elapsed_ms,
                            "generationJobId": child_job_id, "requestPayloadHash": request_hash,
                            "taskId": child_result.get("task_id"),
                            "rootTaskId": (
                                child_result.get("root_task_id")
                                or child_result.get("task_id")
                            ),
                        },
                    })
                _series_patch_attempt(
                    latest, current_item,
                    {
                        "status": "completed", "completedAt": completed_at,
                        "elapsedMs": elapsed_ms, "outputAssetIds": output_asset_ids,
                        "providerTaskId": child_job_id, "requestPayloadHash": request_hash, "error": "",
                    },
                    output_assets=output_assets,
                )
                _series_render_update_item(
                    job_id, item_index, status="completed", completedAt=completed_at,
                    elapsedMs=elapsed_ms, outputAssetIds=output_asset_ids, error=None,
                )
            except Exception as exc:
                any_failed = True
                error = str(exc)
                completed_at = _series_iso_now()
                elapsed_ms = max(0, round((time.time() - started) * 1000))
                current = _load_series_render_job(job_id)
                if current and current.get("status") in {"cancelling", "cancelled"}:
                    try:
                        _series_patch_attempt(
                            current, current["items"][item_index],
                            {"status": "cancelled", "completedAt": completed_at, "elapsedMs": elapsed_ms, "error": "Cancelled"},
                        )
                    except Exception:
                        pass
                    return
                try:
                    _series_patch_attempt(
                        current or latest, (current or latest)["items"][item_index],
                        {"status": "failed", "completedAt": completed_at, "elapsedMs": elapsed_ms, "error": error},
                    )
                except Exception as patch_exc:
                    error = f"{error}; could not persist attempt state: {patch_exc}"
                _series_render_update_item(
                    job_id, item_index, status="failed", completedAt=completed_at,
                    elapsedMs=elapsed_ms, error=error, childJobId=child_job_id,
                )
        latest = _load_series_render_job(job_id) or job
        if latest.get("status") in {"cancelling", "cancelled"}:
            return
        finished = time.time()
        failures = [item for item in latest.get("items", []) if item.get("status") == "failed"]
        _series_render_update(
            job_id,
            status="failed" if failures or any_failed else "completed",
            stage="completed", activeShotId=None, finishedAt=finished,
            error=(f"{len(failures)} shot(s) failed; completed attempts were preserved." if failures else None),
            message=(
                "Render finished with failures. Retry only failed shots when ready."
                if failures else "All requested Series shots completed."
            ),
        )
        _series_settle_episode_render_status(latest)
    except Exception as exc:
        _series_render_update(
            job_id, status="failed", error=str(exc), finishedAt=time.time(),
            message="Series render stopped. Completed attempts were preserved.",
        )
        try:
            _series_settle_episode_render_status(job)
        except Exception:
            pass


def _run_series_render_job(job_id: str) -> None:
    with _series_render_jobs_lock:
        if job_id in _series_render_active_jobs:
            return
        _series_render_active_jobs.add(job_id)
    try:
        _run_series_render_job_inner(job_id)
    finally:
        with _series_render_jobs_lock:
            _series_render_active_jobs.discard(job_id)
        settling = _load_series_render_job(job_id) or {}
        if settling.get("status") == "cancelling":
            settled_items = copy.deepcopy(settling.get("items") or [])
            for item in settled_items:
                if item.get("status") in {"queued", "running", "cancelling"}:
                    item.update({
                        "status": "cancelled",
                        "completedAt": item.get("completedAt") or _series_iso_now(),
                        "error": item.get("error") or "Cancelled by user",
                        "updatedAt": time.time(),
                    })
            _series_render_update(
                job_id,
                items=settled_items,
                status="cancelled",
                stage="cancelled",
                activeShotId=None,
                finishedAt=time.time(),
                message=(
                    "Series render cancelled after the active model thread "
                    "reached a safe boundary. Completed attempts remain available."
                ),
            )
        # Series deliberately marks child generations as one Director-like
        # group so H3 stays warm between adjacent shots. Once the parent job
        # settles, restore the ordinary idle-release policy; otherwise the
        # isolated ConvRot process can retain roughly 50 GB of host RAM forever.
        finished = _load_series_render_job(job_id) or {}
        model_type = str(finished.get("model") or "")
        if _is_legacy_h3_model(model_type):
            _release_legacy_h3_when_queue_allows(job_id)
        elif _is_minimax_h3_model(model_type):
            _release_h3_when_queue_allows(job_id)


def _series_render_candidates(episode: dict, body: dict) -> list[dict]:
    shots = [item for item in episode.get("shots", []) if isinstance(item, dict)]
    mode = str(body.get("mode") or "missing")
    selected_ids = {str(item) for item in body.get("shotIds", []) if isinstance(item, str)}
    if mode == "selected":
        shots = [item for item in shots if item.get("id") in selected_ids]
        if not shots:
            raise ValueError("Select at least one Series shot")
        # Append a new alternative in the same slot while retaining the older
        # approved cut until the user explicitly approves the replacement.
        return shots
    elif mode == "failed":
        shots = [
            item for item in shots
            if item.get("attempts") and item["attempts"][-1].get("status") == "failed"
        ]
    elif mode == "all":
        pass
    elif mode == "missing":
        shots = [item for item in shots if not item.get("approvedAttemptId")]
    else:
        raise ValueError("Render mode must be selected, failed, missing, or all")
    # Bulk generation never spends compute on approved shots. Only explicit
    # per-slot regeneration may append an alternative attempt.
    return [item for item in shots if not item.get("approvedAttemptId")]


@api.post("/api/v1/series/{series_id}/episodes/{episode_id}/render/start")
def start_series_episode_render(series_id: str, episode_id: str, body: dict):
    from services.series_library import append_shot_render_attempt, series_for_episode_snapshot
    from services.series_reference_router import route_shot_references
    from services.series_render import (
        apply_series_shot_duration, model_for_manifest, normalize_series_resolution,
        quantize_h3_frames, series_dialogue_preflight_issues, shot_generation_prompt,
    )

    workspace = _series_library_workspace(body.get("workspace"))
    with _series_library_lock:
        library = _read_series_workspace(workspace)
        series = copy.deepcopy(_series_project_or_404(library, series_id))
        episode = series.get("episodesById", {}).get(episode_id)
        if not isinstance(episode, dict):
            raise HTTPException(status_code=404, detail="Series episode not found")
        active_job = _active_series_render_for_episode(workspace, series_id, episode_id)
        if active_job:
            raise HTTPException(
                status_code=409,
                detail=(
                    f"Series episode already has active render {active_job.get('jobId')}; "
                    "resume or cancel that queue instead of creating duplicate attempts"
                ),
            )
        routing_series = series_for_episode_snapshot(series, episode)
        try:
            candidates = _series_render_candidates(episode, body)
        except ValueError as exc:
            raise HTTPException(status_code=400, detail=str(exc)) from exc
        if not candidates:
            raise HTTPException(status_code=400, detail="No unapproved Series shots match this render request")
        if any(bool(shot.get("dialogueBeats")) for shot in candidates) and not series.get(
            "bestEffortLipSyncAcknowledged"
        ):
            raise HTTPException(
                status_code=400,
                detail=(
                    "Dialogue rendering is blocked until best-effort native lip sync is acknowledged. "
                    "Use ‘I understand · enable dialogue rendering’ in Shots or enable it in Series setup."
                ),
            )
        for shot in candidates:
            apply_series_shot_duration(routing_series, shot)
        dialogue_issues = [
            (shot.get("order"), issue)
            for shot in candidates
            for issue in series_dialogue_preflight_issues(shot, routing_series)
        ]
        if dialogue_issues:
            summary = "; ".join(
                f"shot {order}: {issue}" for order, issue in dialogue_issues[:8]
            )
            if len(dialogue_issues) > 8:
                summary += f"; and {len(dialogue_issues) - 8} more"
            raise HTTPException(
                status_code=400,
                detail=f"Fix dialogue timing/format before rendering: {summary}",
            )
        provider = routing_series.get("provider") if isinstance(routing_series.get("provider"), dict) else {}
        provider_settings = provider.get("videoSettings") if isinstance(provider.get("videoSettings"), dict) else {}
        settings = {**copy.deepcopy(provider_settings), **(
            copy.deepcopy(body.get("settings")) if isinstance(body.get("settings"), dict) else {}
        )}
        resolution, orientation = normalize_series_resolution(
            settings.get("resolution"), settings.get("orientation"),
            provider.get("videoModel") or "minimax_h3",
        )
        settings["resolution"] = resolution
        settings["orientation"] = orientation
        settings["numInferenceSteps"] = max(1, min(50, int(settings.get("numInferenceSteps") or 20)))
        settings["guidanceScale"] = float(settings.get("guidanceScale") or 1)
        settings["flowShift"] = float(settings.get("flowShift") or 12)
        settings["audioShift"] = float(settings.get("audioShift") or 3)
        settings["modelProfile"] = str(settings.get("modelProfile") or "quality")
        settings["fps"] = 24
        try:
            base_seed = int(body.get("seed")) if body.get("seed") is not None else int(uuid.uuid4().hex[:8], 16)
        except (TypeError, ValueError) as exc:
            raise HTTPException(status_code=400, detail="Seed must be an integer") from exc
        items = []
        candidate_ids = {item["id"] for item in candidates}
        for shot_index, shot in enumerate(episode.get("shots", [])):
            if not isinstance(shot, dict) or shot.get("id") not in candidate_ids:
                continue
            manifest = route_shot_references(routing_series, episode, shot, body.get("capabilities"))
            if manifest.get("errors"):
                raise HTTPException(
                    status_code=400,
                    detail=f"Shot {shot.get('order')} reference routing must be fixed: {'; '.join(manifest['errors'])}",
                )
            model = model_for_manifest(str(provider.get("videoModel") or "minimax_h3"), manifest)
            retry_count = len(shot.get("attempts", []))
            apply_series_shot_duration(routing_series, shot)
            duration_contract = shot.get("dialogueDuration") \
                if isinstance(shot.get("dialogueDuration"), dict) else {}
            shot_settings = {
                **settings,
                "requestedDurationSeconds": float(shot.get("durationSeconds") or 0),
                "dialogueDuration": copy.deepcopy(duration_contract),
                "videoLengthFrames": int(duration_contract.get("effectiveFrames"))
                if duration_contract.get("effectiveFrames") is not None
                else quantize_h3_frames(
                    shot.get("durationSeconds"), reference_mode=manifest.get("strategy") == "references",
                ),
            }
            updated_shot, attempt = append_shot_render_attempt(
                shot, manifest=manifest, model=model, settings=shot_settings,
                seed=(base_seed + int(shot.get("order") or shot_index)) & 0x7FFFFFFF,
                retry_count=retry_count, prompt=shot_generation_prompt(
                    routing_series, shot, manifest,
                ),
            )
            episode["shots"][shot_index] = updated_shot
            items.append({
                "shotId": shot["id"], "attemptId": attempt["id"], "status": "queued",
                "childJobId": None, "providerTaskId": None,
                "requestPayloadHash": None, "outputAssetIds": [], "retryCount": retry_count,
                "createdAt": time.time(), "updatedAt": time.time(), "error": None,
            })
        now_iso = _series_iso_now()
        episode["status"] = "rendering"
        episode["updatedAt"] = now_iso
        series["episodesById"][episode_id] = episode
        series["revision"] = int(series.get("revision") or 1) + 1
        series["updatedAt"] = now_iso
        library["seriesById"][series_id] = series
        _write_series_workspace(workspace, library)
        # Persist the episode attempts and their owning job before releasing
        # the library lock. A concurrent start therefore observes this queue
        # and cannot append a second set of attempts for the same episode.
        job_id = f"series-render-{uuid.uuid4().hex[:12]}"
        task_id = f"task-series-render-{job_id}"
        now = time.time()
        job = {
            "jobId": job_id, "kind": "render", "workspace": workspace,
            "seriesId": series_id, "episodeId": episode_id, "status": "queued",
            "stage": "queued", "current": 0, "total": len(items), "items": items,
            "activeShotId": None, "message": "Series shot render queued.",
            "settings": settings, "model": str(provider.get("videoModel") or "minimax_h3"),
            "seed": base_seed, "outputAssetIds": [], "retryCount": 0,
            "createdAt": now, "updatedAt": now, "error": None,
            "taskId": task_id, "rootTaskId": task_id,
        }
        with _series_render_jobs_lock:
            _series_render_jobs[job_id] = job
            _series_render_store(workspace).save(job)
    publisher = globals().get("_publish_series_task")
    task = publisher(job, "series-render") if callable(publisher) else None
    if isinstance(task, dict):
        job["taskId"] = task.get("id")
        job["rootTaskId"] = task.get("root_id") or task.get("id")
        with _series_render_jobs_lock:
            _series_render_jobs[job_id] = copy.deepcopy(job)
            _series_render_store(workspace).save(job)
    threading.Thread(
        target=_run_series_render_job, args=(job_id,),
        name=f"series-render-{job_id[-6:]}", daemon=False,
    ).start()
    return {key: job[key] for key in (
        "jobId", "taskId", "rootTaskId", "workspace", "seriesId", "episodeId",
        "status", "stage", "current",
        "total", "message", "settings", "seed", "createdAt",
    )}


@api.get("/api/v1/series/render/jobs/{job_id}")
def get_series_render_job(job_id: str):
    job = _load_series_render_job(job_id)
    if not job:
        raise HTTPException(status_code=404, detail="Series render job not found")
    return {key: job.get(key) for key in (
        "jobId", "workspace", "seriesId", "episodeId", "status", "stage", "current", "total",
        "items", "activeShotId", "message", "settings", "model", "seed", "error",
        "createdAt", "updatedAt", "finishedAt",
        "taskId", "rootTaskId",
    )}


@api.post("/api/v1/series/render/jobs/{job_id}/cancel")
def cancel_series_render_job(job_id: str):
    job = _load_series_render_job(job_id)
    if not job:
        raise HTTPException(status_code=404, detail="Series render job not found")
    if job.get("status") in {"completed", "failed", "cancelled"}:
        return {"jobId": job_id, "status": job.get("status"), "message": job.get("message")}
    cancelled_at = _series_iso_now()
    with _series_render_jobs_lock:
        worker_active = job_id in _series_render_active_jobs
    active_child = next((
        str(item.get("childJobId")) for item in job.get("items", [])
        if item.get("status") == "running" and item.get("childJobId")
    ), "")
    # A persisted child id can outlive its process after an app restart. Only
    # defer cancellation when there is an in-memory worker that can actually
    # reach a safe boundary; otherwise settle the orphaned checkpoint now.
    active_child_known = bool(active_child and active_child in _jobs)
    deferred = bool(worker_active or active_child_known)
    items = copy.deepcopy(job.get("items") or [])
    cancellable = {"queued", "running"}
    for item in items:
        if item.get("status") in cancellable:
            item.update({
                "status": (
                    "cancelling"
                    if deferred and item.get("status") == "running"
                    else "cancelled"
                ),
                "completedAt": (
                    None
                    if deferred and item.get("status") == "running"
                    else cancelled_at
                ),
                "error": "Cancellation requested", "updatedAt": time.time(),
            })
    updated_job = _series_render_update(
        job_id,
        items=items,
        status="cancelling" if deferred else "cancelled",
        stage="cancelling" if deferred else "cancelled",
        activeShotId=job.get("activeShotId") if deferred else None,
        finishedAt=None if deferred else time.time(),
        message=(
            "Series render cancellation requested; waiting for the active "
            "model thread to reach a safe boundary."
            if deferred else
            "Series render cancelled before model execution."
        ),
    ) or job
    # Persist cancellation for every queued/running attempt too. This keeps
    # recovery honest and guarantees resume appends a fresh attempt instead
    # of rewriting the immutable request metadata of an interrupted one.
    from services.series_library import update_shot_render_attempt
    with _series_library_lock:
        library = _read_series_workspace(str(job["workspace"]))
        series = copy.deepcopy(_series_project_or_404(library, str(job["seriesId"])))
        episode = series.get("episodesById", {}).get(str(job["episodeId"]))
        if isinstance(episode, dict):
            changed = False
            for item in items:
                if item.get("status") != "cancelled":
                    continue
                shot_index = next((
                    index for index, shot in enumerate(episode.get("shots", []))
                    if isinstance(shot, dict) and shot.get("id") == item.get("shotId")
                ), None)
                if shot_index is None:
                    continue
                try:
                    episode["shots"][shot_index] = update_shot_render_attempt(
                        episode["shots"][shot_index], str(item.get("attemptId")),
                        status="cancelled", completedAt=cancelled_at,
                        error="Cancelled by user",
                    )
                    changed = True
                except ValueError:
                    continue
            if changed:
                episode["updatedAt"] = cancelled_at
                series["episodesById"][episode["id"]] = episode
                series["revision"] = int(series.get("revision") or 1) + 1
                series["updatedAt"] = cancelled_at
                library["seriesById"][series["id"]] = series
                _write_series_workspace(str(job["workspace"]), library)
    if active_child and active_child in _jobs:
        _request_generation_cancel(active_child)
    return {
        "jobId": job_id,
        "status": updated_job.get("status"),
        "message": updated_job.get("message") or (
            "Cancellation requested; the active model thread may take a "
            "moment to release."
        ),
    }


@api.get("/api/v1/series/render/recovery")
def list_series_render_recovery(workspace: str | None = None):
    target_workspace = _series_library_workspace(workspace)
    jobs = _series_render_store(target_workspace).recoverable()
    return {"jobs": [{key: job.get(key) for key in (
        "jobId", "seriesId", "episodeId", "status", "stage", "current", "total",
        "activeShotId", "message", "error", "createdAt", "updatedAt",
    )} for job in jobs]}


@api.post("/api/v1/series/render/jobs/{job_id}/resume")
def resume_series_render_job(job_id: str):
    from services.series_library import append_shot_render_attempt, update_shot_render_attempt

    job = _load_series_render_job(job_id)
    if not job:
        raise HTTPException(status_code=404, detail="Series render job not found")
    with _series_render_jobs_lock:
        if job_id in _series_render_active_jobs:
            return {"jobId": job_id, "status": job.get("status"), "message": "Series render is already running."}
    items = copy.deepcopy(job.get("items") or [])
    # A local diffusion process cannot resume mid-step. On explicit recovery,
    # Interrupted/failed/cancelled items get a new append-only attempt;
    # completed items remain untouched and truly queued items retain theirs.
    with _series_library_lock:
        library = _read_series_workspace(str(job["workspace"]))
        series = copy.deepcopy(_series_project_or_404(library, str(job["seriesId"])))
        episode = series.get("episodesById", {}).get(str(job["episodeId"]))
        if not isinstance(episode, dict):
            raise HTTPException(status_code=404, detail="Series episode not found")
        changed = False
        for item_index, item in enumerate(items):
            if item.get("status") in {"completed", "queued"}:
                continue
            shot_index = next((
                index for index, shot in enumerate(episode.get("shots", []))
                if isinstance(shot, dict) and shot.get("id") == item.get("shotId")
            ), None)
            if shot_index is None:
                continue
            shot = episode["shots"][shot_index]
            previous = next((
                value for value in shot.get("attempts", []) if value.get("id") == item.get("attemptId")
            ), None)
            if not isinstance(previous, dict):
                continue
            if previous.get("status") in {"queued", "running"}:
                shot = update_shot_render_attempt(
                    shot, str(previous["id"]), status="cancelled",
                    completedAt=_series_iso_now(), error="Interrupted before recovery",
                )
            resumed_shot, attempt = append_shot_render_attempt(
                shot, manifest=previous.get("referenceManifest") or {},
                model=str(previous.get("model") or job.get("model") or "minimax_h3"),
                settings=previous.get("settings") or job.get("settings") or {},
                seed=previous.get("seed"), retry_count=int(previous.get("retryCount") or 0) + 1,
                prompt=str(previous.get("prompt") or shot.get("prompt") or ""),
            )
            episode["shots"][shot_index] = resumed_shot
            items[item_index] = {
                **item, "attemptId": attempt["id"], "status": "queued", "childJobId": None,
                "providerTaskId": None, "requestPayloadHash": None, "outputAssetIds": [],
                "retryCount": attempt["retryCount"], "error": None, "updatedAt": time.time(),
            }
            changed = True
        if changed:
            now_iso = _series_iso_now()
            episode["updatedAt"] = now_iso
            series["episodesById"][episode["id"]] = episode
            series["revision"] = int(series.get("revision") or 1) + 1
            series["updatedAt"] = now_iso
            library["seriesById"][series["id"]] = series
            _write_series_workspace(str(job["workspace"]), library)
        # Publish the resumed checkpoint before releasing the same lock used
        # by deletion, closing the terminal-job resume/delete race.
        _reset_canonical_task_for_resume(
            str(job.get("workspace") or "default"),
            str(job.get("taskId") or f"task-series-render-{job_id}"),
        )
        _series_render_update(
            job_id, items=items, status="queued", stage="queued", error=None, finishedAt=None,
            message="Resuming Series render; completed shots will be reused.",
        )
    threading.Thread(
        target=_run_series_render_job, args=(job_id,),
        name=f"series-render-{job_id[-6:]}", daemon=False,
    ).start()
    return {"jobId": job_id, "status": "queued", "message": "Series render resumed."}


@api.delete("/api/v1/series/render/jobs/{job_id}")
def discard_series_render_job(job_id: str):
    job = _load_series_render_job(job_id)
    if not job:
        raise HTTPException(status_code=404, detail="Series render job not found")
    with _series_render_jobs_lock:
        if job_id in _series_render_active_jobs:
            raise HTTPException(status_code=409, detail="Cancel the active render before discarding its checkpoint")
        _series_render_store(str(job["workspace"])).discard(job_id)
        _series_render_jobs.pop(job_id, None)
    return {"discarded": True, "jobId": job_id, "outputsPreserved": True}


@api.post("/api/v1/series/{series_id}/episodes/{episode_id}/shots/{shot_id}/attempts/{attempt_id}/approve")
def approve_series_shot_attempt_endpoint(
    series_id: str, episode_id: str, shot_id: str, attempt_id: str, body: dict | None = None,
):
    from services.series_library import approve_shot_render_attempt

    body = body if isinstance(body, dict) else {}
    workspace = _series_library_workspace(body.get("workspace"))
    with _series_library_lock:
        library = _read_series_workspace(workspace)
        series = copy.deepcopy(_series_project_or_404(library, series_id))
        episode = series.get("episodesById", {}).get(episode_id)
        if not isinstance(episode, dict):
            raise HTTPException(status_code=404, detail="Series episode not found")
        shot_index = next((
            index for index, shot in enumerate(episode.get("shots", []))
            if isinstance(shot, dict) and shot.get("id") == shot_id
        ), None)
        if shot_index is None:
            raise HTTPException(status_code=404, detail="Series shot not found")
        try:
            episode["shots"][shot_index] = approve_shot_render_attempt(
                episode["shots"][shot_index], attempt_id,
            )
        except ValueError as exc:
            raise HTTPException(status_code=400, detail=str(exc)) from exc
        now = _series_iso_now()
        if episode.get("shots") and all(
            isinstance(shot, dict) and bool(shot.get("approvedAttemptId"))
            for shot in episode.get("shots", [])
        ):
            episode["status"] = "completed"
        episode["updatedAt"] = now
        series["episodesById"][episode_id] = episode
        series["revision"] = int(series.get("revision") or 1) + 1
        series["updatedAt"] = now
        library["seriesById"][series_id] = series
        stored = _write_series_workspace(workspace, library)
    return stored["seriesById"][series_id]["episodesById"][episode_id]["shots"][shot_index]


@api.post("/api/v1/series/{series_id}/episodes/{episode_id}/attempts/approve-bulk")
def approve_series_episode_attempts_endpoint(
    series_id: str, episode_id: str, body: dict,
):
    from services.series_library import approve_episode_render_attempts

    workspace = _series_library_workspace(body.get("workspace"))
    with _series_library_lock:
        library = _read_series_workspace(workspace)
        series = copy.deepcopy(_series_project_or_404(library, series_id))
        episode = series.get("episodesById", {}).get(episode_id)
        if not isinstance(episode, dict):
            raise HTTPException(status_code=404, detail="Series episode not found")
        try:
            episode = approve_episode_render_attempts(episode, body.get("selections"))
        except ValueError as exc:
            raise HTTPException(status_code=400, detail=str(exc)) from exc
        now = _series_iso_now()
        if episode.get("shots") and all(
            isinstance(shot, dict) and bool(shot.get("approvedAttemptId"))
            for shot in episode.get("shots", [])
        ):
            episode["status"] = "completed"
        episode["updatedAt"] = now
        series["episodesById"][episode_id] = episode
        series["revision"] = int(series.get("revision") or 1) + 1
        series["updatedAt"] = now
        library["seriesById"][series_id] = series
        stored = _write_series_workspace(workspace, library)
    stored_series = stored["seriesById"][series_id]
    return {
        "seriesId": series_id,
        "episodeId": episode_id,
        "revision": stored_series["revision"],
        "episode": stored_series["episodesById"][episode_id],
    }


